  hiddenAttributes?: string[]; // Attributes hidden entirely
  hiddenFromAggregators?: string[]; // Hidden from aggregator dropdown
  hiddenFromDragDrop?: string[]; // Hidden from drag-drop
  unusedOrientationCutoff?: number; // Layout threshold (default 85)
  menuLimit?: number; // Max values in filter menu (default 500)
  // Custom sorters and derived columns
  sorters?: { [attr: string]: any }; // Custom sort order per attribute
  derivedAttributes?: { [name: string]: string }; // Computed columns
  namedOptions?: Record<string, PivotTableOptionsDto>; // componentId → options for aggregator reports
}

@Injectable({
  providedIn: 'root',
})
export class ReportingService {
  constructor(
    protected apiService: ApiService,
    protected settingsService: ConfigurationRepository,
  ) {}

  // V4: base URL for web components (rb-tabulator, rb-chart, rb-pivot-table).
  // Component appends /reports/{id}/data to this — so /api is the right base now.
  get reportingApiBaseUrl(): string {
    return this.apiService.BACKEND_URL;
  }

  async fetchData(
    parameters: { [key: string]: any },
    testMode: boolean = false,
    reportId: string = this.settingsService.currentConfigurationTemplate
      ?.folderName,
  ) {
    const params = new URLSearchParams();
    if (testMode) {
      params.set('testMode', 'true');
    }

    Object.entries(parameters).forEach(([key, value]) => {
      if (value !== null && value !== undefined) {
        params.set(key, value.toString());
      }
    });

    const paramsObj = {};
    params.forEach((value, key) => {
      paramsObj[key] = value;
    });

    const result = await this.apiService.get(
      `/reports/${reportId}/data`,
      paramsObj,
    );
    return result;
  }

  async processGroovyParametersDsl(
    groovyDslCode: string,
    connectionCode?: string,
  ): Promise<ReportParameter[]> {
    const body: any = { dslCode: groovyDslCode };
    if (connectionCode) body.connectionCode = connectionCode;
    const resp = await this.apiService.post(`/dsl/reportparameters/parse`, body);
    return resp?.parameters ?? resp;
  }

  async processGroovyTabulatorDsl(
    groovyDslCode: string,
  ): Promise<TabulatorOptionsDto> {
    const resp = await this.apiService.post(`/dsl/tabulator/parse`, { dslCode: groovyDslCode });
    return resp?.options ?? resp;
  }

  async processGroovyChartDsl(
    groovyDslCode: string,
  ): Promise<ChartOptionsDto> {
    const resp = await this.apiService.post(`/dsl/chart/parse`, { dslCode: groovyDslCode });
    return resp?.options ?? resp;
  }

  async processGroovyPivotTableDsl(
    groovyDslCode: string,
  ): Promise<PivotTableOptionsDto> {
    const resp = await this.apiService.post(`/dsl/pivot/parse`, { dslCode: groovyDslCode });
    return resp?.options ?? resp;
  }
}

import { Injectable, inject } from '@angular/core';
import { ApiService } from './api.service';

export interface CubeDefinition {
  id: string;
  name: string;
  description: string;
  connectionId: string;
  dslCode: string;
  activeClicked?: boolean;
  // True for bundled sample cubes (under config/samples-cubes/) — read-only
  isSample?: boolean;
}

@Injectable({
  providedIn: 'root',
})
export class CubesService {
  cubeDefinitions: CubeDefinition[] = [];

  protected apiService = inject(ApiService);

  async loadAll(): Promise<CubeDefinition[]> {
    const list = await this.apiService.get('/cubes');
    this.cubeDefinitions = (list || []).map((c: any) => ({
      ...c,
      activeClicked: false,
      // Backend returns isSample as the string "true"/"false" — normalize to boolean
      isSample: c.isSample === true || c.isSample === 'true',
    }));
    return this.cubeDefinitions;
  }

  async load(cubeId: string): Promise<CubeDefinition> {
    const result = await this.apiService.get(`/cubes/${encodeURIComponent(cubeId)}`);
    if (result) {
      // Backend returns isSample as boolean here (load uses Map<String,Object>)
      result.isSample = result.isSample === true || result.isSample === 'true';
    }
    return result;
  }

  async save(cubeId: string, data: Partial<CubeDefinition>): Promise<void> {
    return this.apiService.put(`/cubes/${encodeURIComponent(cubeId)}`, data);
  }

  async create(cubeId: string, name: string): Promise<CubeDefinition> {
    return this.apiService.post('/cubes', { cubeId, name });
  }

  async delete(cubeId: string): Promise<void> {
    return this.apiService.delete(`/cubes/${encodeURIComponent(cubeId)}`);
  }

  async duplicate(
    sourceId: string,
    targetId: string,
    targetName: string,
  ): Promise<CubeDefinition> {
    return this.apiService.post(
      `/cubes/${encodeURIComponent(sourceId)}/duplicate`,
      { targetCubeId: targetId, targetName },
    );
  }

  async parseDsl(dslCode: string): Promise<any> {
    return this.apiService.post('/cubes/parse-dsl', { dslCode });
  }

  async generateSqlFromDsl(
    dslCode: string,
    connectionId: string,
    selectedDimensions: string[],
    selectedMeasures: string[],
    selectedSegments: string[] = [],
  ): Promise<{ sql: string; dialect: string }> {
    return this.apiService.post('/cubes/generate-sql', {
      dslCode,
      connectionId,
      selectedDimensions,
      selectedMeasures,
      selectedSegments,
    });
  }

  async generateSql(
    cubeId: string,
    connectionId: string,
    selectedDimensions: string[],
    selectedMeasures: string[],
    selectedSegments: string[] = [],
  ): Promise<{ sql: string; dialect: string }> {
    return this.apiService.post(
      `/cubes/${encodeURIComponent(cubeId)}/generate-sql`,
      { connectionId, selectedDimensions, selectedMeasures, selectedSegments },
    );
  }
}

