@Injectable({
  providedIn: 'root',
})
export class ConfigurationRepository {

  // ====================================================================
  //  In-memory state
  // ====================================================================

  currentConfigurationTemplatePath: string;
  currentConfigurationTemplateName: string;
  currentConfigurationTemplate: CfgTmplFileInfo;

  configurationFiles: Array<CfgTmplFileInfo> = [];
  templateFiles: Array<TmplFileInfo> = [];

  defaultEmailConnectionFile: ExtConnection;
  defaultDatabaseConnectionFile: ExtConnection;

  connectionFiles: Array<ExtConnection> = [];

  numberOfUserVariables: number;

  isLoadingConnections: boolean = false;

  // Cache for loaded DSL details to avoid re-parsing
  private configDetailsCache: Map<string, {
    reportParameters?: ReportParameter[];
    tabulatorOptions?: any;
    chartOptions?: any;
    pivotTableOptions?: any;
  }> = new Map();

  // Magic strings that indicate an unconfigured default email connection
  private static readonly UNCONFIGURED_EMAIL_PLACEHOLDERS = {
    host: 'Email Server Host',
    name: 'From Name',
    fromaddress: 'from@emailaddress.com',
    userid: 'From Email User ID',
    userpassword: 'From Email Password',
  };

  private static readonly TEMPLATE_EXTENSIONS_BY_OUTPUT: Record<string, string[]> = {
    'output.docx':      ['.docx'],
    'output.html':      ['.html'],
    'output.dashboard': ['.html'],
    'output.pdf':       ['.html'],
    'output.xlsx':      ['.html'],
    'output.fop2pdf':   ['.fo', '.xsl', '.xslt'],
  };

  constructor(
    public apiService: ApiService,
    public preferencesService: PreferencesService,
    public appPathsService: AppPathsService,
  ) {}

  // ====================================================================
  //  Pass-through delegates — callers migrated incrementally
  // ====================================================================

  get xmlInternalSettings() { return this.preferencesService.xmlInternalSettings; }
  get showSamples$() { return this.preferencesService.showSamples$; }
  get showSamples() { return this.preferencesService.showSamples; }
  loadPreferences() { return this.preferencesService.loadPreferences(); }
  savePreferences(s: any) { return this.preferencesService.savePreferences(s); }
  getCopilotUrl() { return this.preferencesService.getCopilotUrl(); }

  get LOGS_FOLDER_PATH() { return this.appPathsService.LOGS_FOLDER_PATH; }
  get QUARANTINE_FOLDER_PATH() { return this.appPathsService.QUARANTINE_FOLDER_PATH; }
  get SAMPLES_FOLDER_PATH() { return this.appPathsService.SAMPLES_FOLDER_PATH; }
  get JOBS_FOLDER_PATH() { return this.appPathsService.JOBS_FOLDER_PATH; }
  get CONFIGURATION_FOLDER_PATH() { return this.appPathsService.CONFIGURATION_FOLDER_PATH; }
  get CONFIGURATION_BURST_FOLDER_PATH() { return this.appPathsService.CONFIGURATION_BURST_FOLDER_PATH; }
  get CONFIGURATION_REPORTS_FOLDER_PATH() { return this.appPathsService.CONFIGURATION_REPORTS_FOLDER_PATH; }
  get CONFIGURATION_CONNECTIONS_FOLDER_PATH() { return this.appPathsService.CONFIGURATION_CONNECTIONS_FOLDER_PATH; }
  get CONFIGURATION_DEFAULTS_FOLDER_PATH() { return this.appPathsService.CONFIGURATION_DEFAULTS_FOLDER_PATH; }
  get CONFIGURATION_SAMPLES_FOLDER_PATH() { return this.appPathsService.CONFIGURATION_SAMPLES_FOLDER_PATH; }
  get CONFIGURATION_TEMPLATES_FOLDER_PATH() { return this.appPathsService.CONFIGURATION_TEMPLATES_FOLDER_PATH; }
  get INTERNAL_SETTINGS_FILE_PATH() { return this.appPathsService.INTERNAL_SETTINGS_FILE_PATH; }
  get UPDATE_JAR_FILE_PATH() { return this.appPathsService.UPDATE_JAR_FILE_PATH; }
  get RUNNING_IN_E2E() { return this.appPathsService.RUNNING_IN_E2E; }
  get SHOULD_SEND_STATS() { return this.appPathsService.SHOULD_SEND_STATS; }
  get isWindows() { return this.appPathsService.isWindows; }
  set isWindows(v) { this.appPathsService.isWindows = v; }
  get isServerVersion() { return this.appPathsService.isServerVersion; }
  set isServerVersion(v) { this.appPathsService.isServerVersion = v; }
  get isJServerStarted() { return this.appPathsService.isJServerStarted; }
  set isJServerStarted(v) { this.appPathsService.isJServerStarted = v; }
  get product() { return this.appPathsService.product; }
  set product(v) { this.appPathsService.product = v; }
  get version() { return this.appPathsService.version; }
  set version(v) { this.appPathsService.version = v; }
  getDefaultsConfigurationValuesFilePath() { return this.appPathsService.getDefaultsConfigurationValuesFilePath(); }
  getMyReportsConfigurationValuesFilePath() { return this.appPathsService.getMyReportsConfigurationValuesFilePath(); }

  // ====================================================================
  //  Reports — load & cache
  //  These methods populate this.configurationFiles (the shared in-memory cache).
  //  Decision Log: load methods and filtered-view methods (next region) are intentionally
  //  in the same class — load populates the cache, the views read it. Splitting them into
  //  separate services would expose a mutable cache across a service boundary, which is
  //  a worse design than the current mild size.
  // ====================================================================

  /**
   * MINIMAL LOADING - Fast startup.
   * Returns only basic metadata needed for UI menus (no DSL parsing).
   * DSL options are loaded on-demand via loadReportDetails().
   */
  async loadAllReports({
    forceReload = false,
    withDetails = false,
  }: { forceReload?: boolean; withDetails?: boolean } = {}): Promise<Array<CfgTmplFileInfo>> {
    if (
      !forceReload &&
      this.configurationFiles &&
      this.configurationFiles.length > 0
    )
      return this.configurationFiles;

    if (forceReload) {
      this.configDetailsCache.clear();
    }

    // Use minimal endpoint for fast startup, full endpoint only when explicitly needed
    const endpoint = withDetails ? '/reports?withDetails=true' : '/reports';
    this.configurationFiles = await this.apiService.get(endpoint);

    return this.configurationFiles;
  }

  /**
   * FULL DETAILS LOADING - On-demand for a specific configuration.
   * Loads and caches DSL options (reportParameters, tabulatorOptions, etc.)
   * Merges the loaded details into the existing configurationFiles entry.
   */
  async loadReportDetails(configFile: CfgTmplFileInfo): Promise<CfgTmplFileInfo> {
    if (configFile.type !== 'config-reports' && configFile.type !== 'config-samples' && configFile.type !== 'config-jasper-reports') {
      return configFile;
    }

    const cacheKey = configFile.filePath;

    if (this.configDetailsCache.has(cacheKey)) {
      const cached = this.configDetailsCache.get(cacheKey);
      configFile.reportParameters = cached.reportParameters || [];
      configFile.tabulatorOptions = cached.tabulatorOptions;
      configFile.chartOptions = cached.chartOptions;
      configFile.pivotTableOptions = cached.pivotTableOptions;
      return configFile;
    }

    try {
      const details = await this.apiService.get(`/reports/${encodeURIComponent(configFile.folderName)}`);

      if (details) {
        configFile.reportParameters = details.reportParameters || [];
        configFile.tabulatorOptions = details.tabulatorOptions;
        configFile.chartOptions = details.chartOptions;
        configFile.pivotTableOptions = details.pivotTableOptions;

        this.configDetailsCache.set(cacheKey, {
          reportParameters: configFile.reportParameters,
          tabulatorOptions: configFile.tabulatorOptions,
          chartOptions: configFile.chartOptions,
          pivotTableOptions: configFile.pivotTableOptions,
        });
      }
    } catch (error) {
      console.error(`Failed to load config details for ${configFile.folderName}:`, error);
    }

    return configFile;
  }

  /**
   * Invalidate cached details for a specific configuration.
   * Call this when DSL files are saved/modified to ensure fresh data on next load.
   */
  invalidateConfigDetailsCache(filePath?: string): void {
    if (filePath) {
      this.configDetailsCache.delete(filePath);
    } else {
      this.configDetailsCache.clear();
    }
  }


  async loadAllReportTemplates() {
    this.templateFiles = await this.apiService.get('/reports?type=templates');
    return this.templateFiles;
  }

  // ====================================================================
  //  Reports — filtered views
  //  These methods read from this.configurationFiles (populated by loadAllReports above).
  //  Decision Log: NOT split by report type (Jasper vs. MailMerge/generation vs. Samples)
  //  into separate services. All filters share one cache; splitting would either duplicate
  //  cache management or require cross-service access to the mutable configurationFiles
  //  array — both worse than keeping the filters here as thin one-liners.
  // ====================================================================

  private filterConfigurations(predicate: (c: CfgTmplFileInfo) => boolean): CfgTmplFileInfo[] {
    return this.configurationFiles?.length > 0
      ? this.configurationFiles.filter(predicate)
      : [];
  }

  getNonSampleConfigurations(): CfgTmplFileInfo[] {
    return this.filterConfigurations(c => c.type !== 'config-samples');
  }

  /** @deprecated Use getNonSampleConfigurations() */
  getConfigurations() {
    return this.getNonSampleConfigurations();
  }

  getJasperReportConfigurations(): CfgTmplFileInfo[] {
    return this.filterConfigurations(c => c.type === 'config-jasper-reports');
  }

  getSampleConfigurations(): CfgTmplFileInfo[] {
    return this.filterConfigurations(c => c.type === 'config-samples');
  }

  getReportGenerationConfigurations(filter?: { samples?: boolean }): CfgTmplFileInfo[] {
    return this.filterConfigurations(c => {
      let match = c.capReportGenerationMailMerge && c.dsInputType !== 'ds.dashboard';
      if (filter && !filter.samples) match = match && !c.filePath.includes('samples');
      return match;
    });
  }

  /** @deprecated Use getReportGenerationConfigurations() */
  getMailMergeConfigurations(filter?: { samples?: boolean }) {
    return this.getReportGenerationConfigurations(filter);
  }

  getReportTemplates(outputType: string, options: { samples?: boolean } = {}) {
    const allowedExtensions = ConfigurationRepository.TEMPLATE_EXTENSIONS_BY_OUTPUT[outputType] || [];

    const templatesOfType = this.templateFiles.filter(tplFile =>
      allowedExtensions.some(ext => tplFile.fileName.endsWith(ext))
    );

    // Further filter by configuration folder for DOCX templates only
    let filteredTemplates = templatesOfType;
    if (outputType === 'output.docx' && this.currentConfigurationTemplate?.folderName) {
      const folderToMatch = `/reports/${this.currentConfigurationTemplate.folderName}/`;
      filteredTemplates = templatesOfType.filter(tplFile =>
        tplFile.filePath.includes(folderToMatch)
      );
    }

    if (options && options.hasOwnProperty('samples')) {
      return filteredTemplates.filter(tplFile => {
        if (options.samples) return tplFile.type.includes('-sample');
        return !tplFile.type.includes('-sample');
      });
    }

    return filteredTemplates;
  }

  // ====================================================================
  //  Connections — load, cache, derived state
  // ====================================================================

  get emailConnections(): ExtConnection[] {
    return this.connectionFiles.filter(c => c.connectionType === 'email-connection');
  }

  get databaseConnections(): ExtConnection[] {
    return this.connectionFiles.filter(c => c.connectionType === 'database-connection');
  }

  /** @deprecated Use emailConnections getter */
  getEmailConnectionFiles(): ExtConnection[] {
    return this.emailConnections;
  }

  /** @deprecated Use databaseConnections getter */
  getDatabaseConnectionFiles(): ExtConnection[] {
    return this.databaseConnections;
  }

  // Potential race: concurrent callers get undefined instead of waiting. Assumed safe
  // (call sites are route-separated); fix with Promise singleton if symptoms appear.
  async loadAllConnections() {
    if (this.isLoadingConnections) return;
    this.isLoadingConnections = true;
    try {
      const fresh = await this.fetchConnectionsFromBackend();
      this.connectionFiles = fresh.map(conn => ({ ...conn, usedBy: this.computeUsedByForConnection(conn) }));
      this.memoizeDefaultConnections();
    } finally {
      this.isLoadingConnections = false;
    }
    return this.connectionFiles;
  }

  private async fetchConnectionsFromBackend(): Promise<ExtConnection[]> {
    const [email, db] = await Promise.all([
      this.apiService.get('/connections?type=email'),
      this.apiService.get('/connections?type=database'),
    ]);
    return [...(email || []), ...(db || [])];
  }

  private memoizeDefaultConnections() {
    this.defaultEmailConnectionFile = this.getConnectionDetails({
      connectionType: 'email-connection',
      defaultConnection: true,
      connectionCode: '',
    });
    this.defaultDatabaseConnectionFile = this.getConnectionDetails({
      connectionType: 'database-connection',
      defaultConnection: true,
      connectionCode: '',
    });
  }

  // Load-bearing cross-cluster join: reads configurationFiles (Reports cluster) to annotate
  // each connection with the report templates that reference it. This join is why both
  // clusters live in one class — splitting them would force this cross-cluster read across
  // a service boundary with no design benefit.
  private computeUsedByForConnection(conn: ExtConnection): string {
    const matchingTemplates = this.configurationFiles
      .filter(c => {
        if (c.type === 'config-samples') return false;
        if (conn.connectionType === 'email-connection') {
          return c.useEmlConn && c.emlConnCode == conn.connectionCode;
        }
        // database-connection: SQL/Script reports + JasperReports
        return (c.useDbConn && c.dbConnCode == conn.connectionCode)
          || c.dbConnectionCode == conn.connectionCode;
      })
      .map(c => c.templateName);
    return matchingTemplates.join(', ') || '--not used--';
  }

  recomputeConnectionUsage(
    filePath: string,
    xmlSettings: {
      documentburster: any;
    },
  ) {
    // Update the specific configuration file's connection metadata
    const configToUpdate = this.configurationFiles.find(
      (config) => config.filePath === filePath,
    );

    if (configToUpdate) {
      configToUpdate.useEmlConn =
        xmlSettings?.documentburster.settings.emailserver.useconn;
      configToUpdate.emlConnCode =
        xmlSettings?.documentburster.settings.emailserver.conncode;
    }

    // Recalculate "Used By" for all connections using the updated configuration
    this.connectionFiles = this.connectionFiles.map((connFile) => ({
      ...connFile,
      usedBy: this.computeUsedByForConnection(connFile),
    }));
  }

  /** @deprecated Use recomputeConnectionUsage() */
  refreshConnectionsUsedByInformation(
    filePath: string,
    xmlSettings: {
      documentburster: any;
    },
  ) {
    return this.recomputeConnectionUsage(filePath, xmlSettings);
  }

  isDefaultEmailConnectionConfigured(): boolean {
    const ph = ConfigurationRepository.UNCONFIGURED_EMAIL_PLACEHOLDERS;
    return (
      this.defaultEmailConnectionFile &&
      this.defaultEmailConnectionFile.emailserver &&
      this.defaultEmailConnectionFile.emailserver.host !== ph.host &&
      this.defaultEmailConnectionFile.emailserver.name !== ph.name &&
      this.defaultEmailConnectionFile.emailserver.fromaddress !== ph.fromaddress &&
      this.defaultEmailConnectionFile.emailserver.userid !== ph.userid &&
      this.defaultEmailConnectionFile.emailserver.userpassword !== ph.userpassword
    );
  }

  getConnectionDetails({
    connectionType,
    defaultConnection,
    connectionCode,
  }: {
    connectionType: string;
    defaultConnection: boolean;
    connectionCode: string;
  }) {
    let connFiles = [];

    if (this.connectionFiles.length > 0) {
      connFiles = this.connectionFiles.filter((connection: ExtConnection) => {
        return connection.connectionType == connectionType;
      });

      if (defaultConnection) {
        connFiles = connFiles.filter((connection: ExtConnection) => {
          return connection.defaultConnection;
        });
      }

      if (connectionCode && connectionCode.length > 0) {
        connFiles = connFiles.filter((connection: ExtConnection) => {
          return connection.connectionCode == connectionCode;
        });
      }

      if (connFiles && connFiles.length == 1) {
        return connFiles[0];
      }
    }
    return undefined;
  }
}

import { Injectable, inject } from '@angular/core';
import { ApiService } from './api.service';
import { APP_CONFIG } from '../../environments/environment';

export interface TmplFileInfo {
  fileName: string;
  filePath: string;
  type: string;
  content?: string;
  folderName: string;
  relativeFilePath: string;
}

export interface ReportParameter {
  id: string;
  type: string;
  value?: any;
  label?: string;
  description?: string;
  defaultValue?: any;
  constraints?: {
    [key: string]: any;
    required?: boolean;
    min?: number | string;
    max?: number | string;
    pattern?: string;
  };
  uiHints?: {
    [key: string]: any;
    control?: string;
    list?: any[];
    sql?: string;
  };
}

export interface CfgTmplFileInfo {
  fileName: string;
  filePath: string;
  templateName: string;
  capReportGenerationMailMerge: boolean;
  capReportDistribution: boolean;
  dsInputType: string;
  notes: string;
  type: string;
  folderName: string;
  relativeFilePath: string;
  isFallback: boolean;
  scriptOptionsSelectFileExplorer: string;
  activeClicked?: boolean;
  useEmlConn?: boolean;
  emlConnCode?: string;

  // For JasperReports: DB connection code (from datasource.properties or default)
  dbConnectionCode?: string;

  reportParameters: ReportParameter[];

  // Parsed Tabulator DSL options -- flat map matching tabulator.info constructor options
  tabulatorOptions?: {
    columns?: Array<{ title?: string; field?: string; [k: string]: any }>;
    data?: Array<Record<string, any>>;
    [k: string]: any; // all other tabulator.info options (layout, height, pagination, etc.)
  };

  // Parsed Chart DSL options (type, labelField, options, labels, datasets, data)
  chartOptions?: {
    type?: string;
    labelField?: string;
    options?: any;
    labels?: string[];
    datasets?: Array<{ field?: string; label?: string; color?: string; type?: string; [k: string]: any }>;
    data?: Array<Record<string, any>>;
  };

  // Parsed Pivot Table DSL options
  pivotTableOptions?: {
    rows?: string[];
    cols?: string[];
    vals?: string[];
    aggregatorName?: string;
    rendererName?: string;
    rowOrder?: string;
    colOrder?: string;
    valueFilter?: Record<string, any>;
    options?: any;
    data?: Array<Record<string, any>>;
    hiddenAttributes?: string[];
    hiddenFromAggregators?: string[];
    hiddenFromDragDrop?: string[];
    unusedOrientationCutoff?: number;
    menuLimit?: number;
    sorters?: Record<string, any>;
    derivedAttributes?: Record<string, string>;
  };
}

@Injectable({
  providedIn: 'root',
})
export class ReportsService {

  configurationFiles: Array<CfgTmplFileInfo> = [];
  templateFiles: Array<TmplFileInfo> = [];

  CONFIGURATION_FOLDER_PATH: string;
  CONFIGURATION_REPORTS_FOLDER_PATH: string;
  CONFIGURATION_DEFAULTS_FOLDER_PATH: string;
  CONFIGURATION_SAMPLES_FOLDER_PATH: string;
  CONFIGURATION_BURST_FOLDER_PATH: string;
  CONFIGURATION_TEMPLATES_FOLDER_PATH: string;
  INTERNAL_SETTINGS_FILE_PATH: string;

  currentConfigurationTemplatePath: string;
  currentConfigurationTemplateName: string;
  currentConfigurationTemplate: CfgTmplFileInfo;

  product: string = 'DocumentBurster';
  version: any;
  isWindows: boolean = false;
  isServerVersion: boolean = false;
  numberOfUserVariables: number;

  // Cache for loaded DSL details to avoid re-parsing
  private configDetailsCache: Map<string, {
    reportParameters?: ReportParameter[];
    tabulatorOptions?: any;
    chartOptions?: any;
    pivotTableOptions?: any;
  }> = new Map();

  public apiService = inject(ApiService);

  constructor() {
    this.CONFIGURATION_FOLDER_PATH = `${APP_CONFIG.folders.config}`;
    this.INTERNAL_SETTINGS_FILE_PATH = `${this.CONFIGURATION_FOLDER_PATH}/_internal/settings.xml`;
    this.CONFIGURATION_DEFAULTS_FOLDER_PATH = `${this.CONFIGURATION_FOLDER_PATH}/_defaults`;
    this.CONFIGURATION_BURST_FOLDER_PATH = `${APP_CONFIG.folders.config}/burst`;
    this.CONFIGURATION_REPORTS_FOLDER_PATH = `${APP_CONFIG.folders.config}/reports`;
    this.CONFIGURATION_SAMPLES_FOLDER_PATH = `${APP_CONFIG.folders.config}/samples`;
    this.CONFIGURATION_TEMPLATES_FOLDER_PATH = `templates`;
  }

  getDefaultsConfigurationValuesFilePath(): string {
    return `${this.CONFIGURATION_DEFAULTS_FOLDER_PATH}/settings.xml`;
  }

  getMyReportsConfigurationValuesFilePath(): string {
    return `${this.CONFIGURATION_BURST_FOLDER_PATH}/settings.xml`;
  }

  async loadImageAsDataUrl(imagePath: string): Promise<string> {
    // Important: Explicitly set Accept header to image/*
    const response = await fetch(
      `/api/reports/serve-asset?path=${encodeURIComponent(imagePath)}`,
      {
        headers: {
          Accept: 'image/*', // This is critical
        },
      },
    );

    if (!response.ok) {
      console.error(
        `Failed to load image: ${imagePath}, status: ${response.status}`,
      );
      return null;
    }

    const blob = await response.blob();

    // Convert blob to data URL
    return new Promise((resolve) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve(reader.result as string);
      reader.readAsDataURL(blob);
    });
  }

  // ===== NEW ID-based methods =====

  async loadDefaults(): Promise<any> {
    const systemInfo = await this.apiService.get('/system/info');

    if (!systemInfo) {
      return;
    }

    this.isWindows = systemInfo.osName.startsWith('Windows');

    this.product = systemInfo.product;

    if (this.product.toLowerCase().includes('server')) {
      this.isServerVersion = true;
    }

    let xmlSettings = {
      documentburster: {
        settings: null,
      },
    };

    xmlSettings.documentburster = await this.apiService.get('/reports/_defaults/settings');

    this.version = xmlSettings.documentburster.settings.version;

    return xmlSettings;
  }

  async loadReportSettings(reportId: string): Promise<{
    documentburster: {
      settings: any;
    };
  }> {
    let xmlSettings = {
      documentburster: { settings: {} },
    };

    xmlSettings.documentburster = await this.apiService.get(
      `/reports/${encodeURIComponent(reportId)}/settings`,
    );

    return xmlSettings;
  }

  async loadSettingsByPath(configFilePath: string): Promise<{
    documentburster: {
      settings: any;
    };
  }> {
    let xmlSettings = {
      documentburster: { settings: {} },
    };

    // Extract reportId from paths like "config/reports/my-report/settings.xml"
    const parts = configFilePath.replace(/\\/g, '/').split('/');
    const reportId = parts.length >= 2 ? parts[parts.length - 2] : '_defaults';
    const result = await this.apiService.get(
      `/reports/${encodeURIComponent(reportId)}/settings`,
    );
    console.log('[RB-DIAG] loadSettingsByPath reportId:', reportId, 'result keys:', result ? Object.keys(result) : result);
    xmlSettings.documentburster = result;

    return xmlSettings;
  }

  async saveReportSettings(
    reportId: string,
    xmlSettings: {
      documentburster: any;
    },
  ) {
    xmlSettings.documentburster.settings?.attachments?.items?.attachmentItems?.forEach(
      (item: { selected?: boolean }) => {
        delete item.selected;
      },
    );

    return this.apiService.put(
      `/reports/${encodeURIComponent(reportId)}/settings`,
      xmlSettings.documentburster,
    );
  }

  async loadReportDataSource(reportId: string): Promise<any> {
    return this.apiService.get(
      `/reports/${encodeURIComponent(reportId)}/datasource`,
    );
  }

  async saveReportDataSource(
    reportId: string,
    xmlReporting: { documentburster: {} },
  ) {
    return this.apiService.put(
      `/reports/${encodeURIComponent(reportId)}/datasource`,
      xmlReporting.documentburster,
    );
  }

  /**
   * Load template content for a specific output type.
   * Backend computes the path: templates/reports/{reportId}/{reportId}-{type}.{ext}
   * Each output type has its own template file.
   */
  async loadReportTemplateByType(reportId: string, outputType: string): Promise<string> {
    const textHeaders = new Headers({ Accept: 'text/plain' });
    return this.apiService.get(
      `/reports/${encodeURIComponent(reportId)}/template/${encodeURIComponent(outputType)}`,
      undefined,
      textHeaders,
      'text',
    );
  }

  /**
   * Save template content for a specific output type.
   */
  async saveReportTemplateByType(reportId: string, outputType: string, content: string, assetSourceDir?: string): Promise<{ documentpath?: string }> {
    const textHeaders = new Headers({ 'Content-Type': 'text/plain' });
    const assetParam = assetSourceDir ? `?assetSourceDir=${encodeURIComponent(assetSourceDir)}` : '';
    return this.apiService.put(
      `/reports/${encodeURIComponent(reportId)}/template/${encodeURIComponent(outputType)}${assetParam}`,
      content,
      textHeaders,
    );
  }

  /**
   * Load template content for a report.
   * Backend resolves the template path from the report's config — no type needed.
   */
  async loadReportTemplate(reportId: string): Promise<string> {
    const result = await this.apiService.get(
      `/reports/${encodeURIComponent(reportId)}/template`,
      undefined,
      new Headers({
        Accept: 'text/plain',
        'Content-Type': 'application/json',
      }),
      'text',
    );

    return result || '';
  }

  /**
   * Save template content for a report.
   * Backend resolves the template path from the report's config.
   */
  /**
   * Load a Groovy DSL script (tabulator, chart, pivot, datasource, etc.) by reportId and type.
   */
  async loadReportScript(reportId: string, scriptType: string): Promise<string> {
    const textHeaders = new Headers({ Accept: 'text/plain' });
    return this.apiService.get(
      `/reports/${encodeURIComponent(reportId)}/script/${encodeURIComponent(scriptType)}`,
      undefined,
      textHeaders,
      'text',
    );
  }

  /**
   * Save a Groovy DSL script by reportId and type.
   */
  async saveReportScript(reportId: string, scriptType: string, content: string) {
    const textHeaders = new Headers({ 'Content-Type': 'text/plain' });
    return this.apiService.put(
      `/reports/${encodeURIComponent(reportId)}/script/${encodeURIComponent(scriptType)}`,
      content,
      textHeaders,
    );
  }

  async saveReportTemplate(reportId: string, content: string) {
    const textHeaders = new Headers({ 'Content-Type': 'text/plain' });
    return this.apiService.put(
      `/reports/${encodeURIComponent(reportId)}/template`,
      content,
      textHeaders,
    );
  }

  /**
   * MINIMAL LOADING - Fast startup.
   * Returns only basic metadata needed for UI menus (no DSL parsing).
   * DSL options are loaded on-demand via loadReportDetails().
   */
  async loadAllReports({
    forceReload = false,
    fullLoad = false,  // Set to true for backward-compat scenarios needing all details upfront
  }: { forceReload?: boolean; fullLoad?: boolean } = {}): Promise<Array<CfgTmplFileInfo>> {
    if (
      !forceReload &&
      this.configurationFiles &&
      this.configurationFiles.length > 0
    )
      return this.configurationFiles;

    // Clear cache on force reload
    if (forceReload) {
      this.configDetailsCache.clear();
    }

    // Use minimal endpoint for fast startup, full endpoint only when explicitly needed
    const endpoint = fullLoad ? '/reports?withDetails=true' : '/reports';
    this.configurationFiles = await this.apiService.get(endpoint);

    return this.configurationFiles;
  }

  /**
   * FULL DETAILS LOADING - On-demand for a specific configuration.
   * Loads and caches DSL options (reportParameters, tabulatorOptions, etc.)
   * Merges the loaded details into the existing configurationFiles entry.
   *
   * @param configFile The configuration to load details for
   * @returns The updated configuration with DSL options populated
   */
  async loadReportDetails(configFile: CfgTmplFileInfo): Promise<CfgTmplFileInfo> {
    // Only reports, samples, and jasper reports have details to load
    if (configFile.type !== 'config-reports' && configFile.type !== 'config-samples' && configFile.type !== 'config-jasper-reports') {
      return configFile;
    }

    const cacheKey = configFile.filePath;

    // Check cache first
    if (this.configDetailsCache.has(cacheKey)) {
      const cached = this.configDetailsCache.get(cacheKey);
      configFile.reportParameters = cached.reportParameters || [];
      configFile.tabulatorOptions = cached.tabulatorOptions;
      configFile.chartOptions = cached.chartOptions;
      configFile.pivotTableOptions = cached.pivotTableOptions;
      return configFile;
    }

    try {
      const details = await this.apiService.get(`/reports/${encodeURIComponent(configFile.folderName)}`);

      if (details) {
        // Merge loaded details into the config
        configFile.reportParameters = details.reportParameters || [];
        configFile.tabulatorOptions = details.tabulatorOptions;
        configFile.chartOptions = details.chartOptions;
        configFile.pivotTableOptions = details.pivotTableOptions;

        // Cache the results
        this.configDetailsCache.set(cacheKey, {
          reportParameters: configFile.reportParameters,
          tabulatorOptions: configFile.tabulatorOptions,
          chartOptions: configFile.chartOptions,
          pivotTableOptions: configFile.pivotTableOptions,
        });
      }
    } catch (error) {
      console.error(`Failed to load config details for ${configFile.folderName}:`, error);
    }

    return configFile;
  }

  /**
   * Invalidate cached details for a specific configuration.
   * Call this when DSL files are saved/modified to ensure fresh data on next load.
   */
  invalidateConfigDetailsCache(filePath?: string): void {
    if (filePath) {
      this.configDetailsCache.delete(filePath);
    } else {
      // Clear entire cache
      this.configDetailsCache.clear();
    }
  }

  // ===== Gallery template methods (ID-based, no paths) =====

  /**
   * Load gallery template HTML content + asset base directory.
   */
  async loadGalleryTemplateContent(
    templateId: string,
    variant: number = 0,
  ): Promise<{ content: string; assetBaseDir: string }> {
    return this.apiService.get(`/system/gallery/templates/${encodeURIComponent(templateId)}/content`, { variant });
  }

  /**
   * Load gallery template README.
   */
  async loadGalleryTemplateReadme(templateId: string, variant: number = 0): Promise<string> {
    const textHeaders = new Headers({ Accept: 'text/plain' });
    return this.apiService.get(
      `/system/gallery/templates/${encodeURIComponent(templateId)}/readme`,
      { variant },
      textHeaders,
      'text',
    );
  }

  /**
   * Load gallery template AI prompt (type: 'modify' or 'scratch').
   */
  async loadGalleryTemplateAiPrompt(
    templateId: string,
    type: 'modify' | 'scratch',
    variant: number = 0,
  ): Promise<string> {
    const textHeaders = new Headers({ Accept: 'text/plain' });
    return this.apiService.get(
      `/system/gallery/templates/${encodeURIComponent(templateId)}/ai-prompt`,
      { type, variant },
      textHeaders,
      'text',
    );
  }

  /**
   * Get the URL to view a gallery template in the browser.
   */
  getGalleryTemplateViewUrl(templateId: string, variant: number = 0): string {
    return `/api/system/gallery/templates/${encodeURIComponent(templateId)}/view?variant=${variant}`;
  }

  async loadAllReportTemplates() {
    this.templateFiles = await this.apiService.get('/reports?type=templates');
    return this.templateFiles;
  }

  getConfigurations() {
    if (this.configurationFiles && this.configurationFiles.length > 0) {
      return this.configurationFiles.filter(
        (configuration) => configuration.type != 'config-samples',
      );
    }
  }

  getMailMergeConfigurations(filter?: { samples?: boolean }) {
    if (this.configurationFiles && this.configurationFiles.length > 0) {
      return this.configurationFiles.filter((configuration) => {
        let filterCondition = configuration.capReportGenerationMailMerge;

        if (filterCondition)
          filterCondition =
            filterCondition && configuration.dsInputType !== 'ds.dashboard';

        if (filter && !filter.samples)
          filterCondition =
            filterCondition && !configuration.filePath.includes('samples');

        return filterCondition;
      });
    }
  }

  getSampleConfigurations() {
    if (this.configurationFiles && this.configurationFiles.length > 0) {
      return this.configurationFiles.filter(
        (configuration) => configuration.type == 'config-samples',
      );
    }
  }

  getJasperReportConfigurations() {
    if (this.configurationFiles && this.configurationFiles.length > 0) {
      return this.configurationFiles.filter(
        (configuration) => configuration.type === 'config-jasper-reports',
      );
    }
    return [];
  }

  getReportTemplates(outputType: string, options: any = {}) {
    // Filter templates by output type
    const templatesOfType = this.templateFiles.filter((tplFile) => {
      if (outputType === 'output.docx' && tplFile.fileName.endsWith('.docx'))
        return true;
      if (
        (outputType === 'output.html' ||
          outputType === 'output.dashboard' ||
          outputType === 'output.pdf' ||
          outputType === 'output.xlsx') &&
        tplFile.fileName.endsWith('.html')
      )
        return true;

      if (
        outputType === 'output.fop2pdf' &&
        (tplFile.fileName.endsWith('.fo') || tplFile.fileName.endsWith('.xsl') || tplFile.fileName.endsWith('.xslt'))
      )
        return true;

      return false;
    });

    // Further filter by configuration folder for DOCX templates only
    let filteredTemplates = templatesOfType;
    if (
      outputType === 'output.docx' &&
      this.currentConfigurationTemplate?.folderName
    ) {
      const folderToMatch = `/reports/${this.currentConfigurationTemplate.folderName}/`;
      filteredTemplates = templatesOfType.filter((tplFile) => {
        // Only include templates that are in the specific subfolder matching the current configuration
        return tplFile.filePath.includes(folderToMatch);
      });
    }

    // Apply sample filter if needed
    if (options && options.hasOwnProperty('samples')) {
      return filteredTemplates.filter((tplFile) => {
        if (options.samples) return tplFile.type.includes('-sample');
        return !tplFile.type.includes('-sample');
      });
    }

    return filteredTemplates;
  }

  // --- NEW atomic methods for report CRUD operations ---

  async createReport(
    reportId: string,
    templateName: string,
    capReportDistribution: boolean,
    capReportGenerationMailMerge: boolean,
    copyFromReportId?: string,
  ): Promise<CfgTmplFileInfo> {
    return this.apiService.post('/reports', {
      reportId,
      templateName,
      capReportDistribution,
      capReportGenerationMailMerge,
      copyFromReportId,
    });
  }

  async duplicateReport(
    sourceReportId: string,
    targetReportId: string,
    templateName: string,
    capReportDistribution: boolean,
    capReportGenerationMailMerge: boolean,
  ): Promise<CfgTmplFileInfo> {
    return this.apiService.post(
      `/reports/${sourceReportId}/duplicate`,
      {
        targetReportId,
        templateName,
        capReportDistribution,
        capReportGenerationMailMerge,
      },
    );
  }

  async deleteReport(reportId: string): Promise<void> {
    return this.apiService.delete(`/reports/${reportId}`);
  }

  async restoreDefaults(reportId: string): Promise<void> {
    return this.apiService.post(
      `/reports/${reportId}/restore-defaults`,
    );
  }

  requiresInputFile(report: CfgTmplFileInfo): boolean {
    if (!report) return true;
    if (report.dsInputType === 'ds.jasper') return false;
    if (report.dsInputType === 'ds.sqlquery') return false;
    if (report.dsInputType === 'ds.scriptfile') {
      const sel = (report.scriptOptionsSelectFileExplorer ?? 'notused');
      return sel !== 'notused';
    }
    return true;
  }

  requiresParameters(report: CfgTmplFileInfo): boolean {
    if (!report) return true;
    return !!(report.reportParameters && report.reportParameters.length > 0);
  }

  allowedInputFileTypes(report: CfgTmplFileInfo): string {
    if (!report) return 'notused';
    const dsInputType = report.dsInputType;
    const scriptOptionsSelectFileExplorer = report.scriptOptionsSelectFileExplorer;
    if (!dsInputType) return 'notused';
    if (['ds.csvfile', 'ds.tsvfile', 'ds.fixedwidthfile'].includes(dsInputType))
      return '.csv, .tsv, .tab, .txt, .prn, .dat';
    if (dsInputType === 'ds.xmlfile') return '.xml';
    if (dsInputType === 'ds.excelfile') return '.xlsx, .xls';
    if (dsInputType === 'ds.script') return scriptOptionsSelectFileExplorer;
    return 'notused';
  }

  convertParamValue(type: string, value: any): any {
    switch (type) {
      case 'LocalDate':
      case 'LocalDateTime':
        return value;
      case 'Integer':
        return parseInt(value, 10);
      case 'Boolean':
        return Boolean(value);
      default:
        return value;
    }
  }

}

import {
  Component,
  input,
  model,
  output,
  TemplateRef,
  viewChild,
  ElementRef,
  OnInit,
  OnChanges,
  SimpleChanges,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { TreeNodeComponent } from './tree-node.component'; // Import the node component

// Define TreeNode interface (can be in its own file)
export interface TreeNode {
  key?: string;
  label: string;
  data?: any;
  icon?: string;
  expandedIcon?: string;
  collapsedIcon?: string;
  children?: TreeNode[];
  expanded?: boolean;
  type?: string;
  parent?: TreeNode;
  partialSelected?: boolean;
  styleClass?: string;
  draggable?: boolean;
  droppable?: boolean;
  selectable?: boolean;
  leaf?: boolean;
  style?: string;
  visible?: boolean; // Added for filtering
  // Used by the picklist's `flattenGroupNodes` mode. When set, the node is
  // treated as a "leaf" that, when moved back from target to source, is
  // re-grouped under a parent node identified by `originalParentKey`. The
  // picklist creates the parent group on demand if it no longer exists in
  // the source.
  originalParentKey?: string;
  originalParentLabel?: string;
}

@Component({
    selector: 'dburst-tree',
    standalone: true,
    imports: [CommonModule, FormsModule, TreeNodeComponent], // Import CustomTreeNodeComponent here
    template: `
    <div
      id="{{ treeId() }}"
      class="p-tree p-component"
      [ngClass]="{
        'p-tree-selectable': !!selectionMode(),
        'p-tree-loading': loading(),
      }"
      >
      @if (loading() && loadingMode() === 'mask') {
        <div
          class="p-tree-mask p-overlay-mask"
          >
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" class="p-tree-loading-icon inline-block w-4 h-4 animate-spin"><path stroke-linecap="round" stroke-linejoin="round" d="M16.023 9.348h4.992v-.001M2.985 19.644v-4.992m0 0h4.992m-4.993 0l3.181 3.183a8.25 8.25 0 0013.803-3.7M4.031 9.865a8.25 8.25 0 0113.803-3.7l3.181 3.182m0-4.991v4.99"/></svg>
        </div>
      }

      @if (filter()) {
        <div class="p-tree-filter-container">
          <input
            #filterInput
            id="filterInput{{ treeId() }}"
            type="text"
            class="p-tree-filter p-inputtext p-component"
            [attr.placeholder]="filterPlaceholder() || 'Filter'"
            (input)="onFilterKeyup($event)"
            />
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" class="p-tree-filter-icon inline-block w-4 h-4"><path stroke-linecap="round" stroke-linejoin="round" d="M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 15.803 7.5 7.5 0 0015.803 15.803z"/></svg>
          </div>
        }

        <div class="p-tree-wrapper" [style.max-height]="scrollHeight()">
          <ul class="p-tree-container p-tree-root-children" role="tree">
            @for (node of visibleNodes; track trackBy($index, node)) {
              <dburst-tree-node
                [node]="node"
                [level]="0"
                [indentation]="indentation()"
                [selectable]="isSelectable()"
                [checkboxMode]="selectionMode() === 'checkbox'"
                [isSelected]="isSelected(node)"
                [selection]="selection()"
                [treeId]="treeId()"
                [showTooltips]="showTooltips()"
            [nodeTemplate]="
              nodeTemplate() || _templateMap()?.[node.type || 'default']
            "
                (nodeSelect)="handleNodeSelect($event)"
                (nodeUnselect)="handleNodeUnselect($event)"
                (nodeToggle)="handleNodeToggle($event)"
                (nodeWeakClick)="nodeWeakClick.emit($event)"
                >
              </dburst-tree-node>
            }
          </ul>
          @if (isEmpty()) {
            <div class="p-tree-empty-message">
              {{ emptyMessage() || 'No records found' }}
            </div>
          }
        </div>
      </div>
    `,
    styles: [
        `
      :host {
        display: block;
      }
      /* Base Tree Styles */
      .p-tree {
        background: #ffffff; /* dt('tree.background') */
        color: #4b5563; /* dt('tree.color') */
        padding: 0.5rem; /* dt('tree.padding') */
        border: 1px solid #dee2e6; /* Example border */
        border-radius: 6px; /* Example border-radius */
        position: relative; /* Needed for mask */
        overflow: hidden; /* Contain elements */
      }
      .p-tree-wrapper {
        overflow: auto; /* Enable scrolling if needed */
      }
      .p-tree-container.p-tree-root-children {
        display: flex;
        list-style-type: none;
        flex-direction: column;
        margin: 0;
        padding: 0;
        gap: 0px; /* dt('tree.gap') - Adjust as needed */
        padding-block-start: 0px; /* dt('tree.gap') */
      }

      /* Filter Styles */
      .p-tree-filter-container {
        position: relative;
        margin-bottom: 0.5rem; /* Spacing */
      }
      .p-tree-filter {
        width: 100%;
        padding: 0.5rem 0.75rem; /* Basic input padding */
        padding-right: 2.5rem; /* Space for icon */
        border: 1px solid #ced4da;
        border-radius: 6px;
        box-sizing: border-box; /* Include padding and border in width */
      }
      .p-tree-filter-icon {
        position: absolute;
        top: 50%;
        right: 0.75rem;
        transform: translateY(-50%);
        color: #6c757d;
      }

      /* Loading Mask Styles */
      .p-tree-mask {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: rgba(255, 255, 255, 0.4); /* Semi-transparent white */
        display: flex;
        align-items: center;
        justify-content: center;
        z-index: 10; /* Ensure it's above content */
      }
      .p-tree-loading-icon {
        font-size: 2rem; /* dt('tree.loading.icon.size') */
        width: 2rem;
        height: 2rem;
        color: var(
          --primary-color,
          #10b981
        ); /* Use primary color if available */
      }
      /* Add pi-spin animation if not globally available */
      @keyframes pi-spin {
        100% {
          transform: rotate(360deg);
        }
      }
      .pi-spin {
        animation: pi-spin 1s linear infinite;
      }

      /* Empty Message Styles */
      .p-tree-empty-message {
        padding: 1rem;
        text-align: center;
        color: #6c757d;
      }
    `,
    ]
})
export class TreeComponent implements OnInit, OnChanges {
  treeId = input<string | undefined>(undefined);

  value = input<TreeNode[]>([]);
  selectionMode = input<'single' | 'multiple' | 'checkbox' | null>(null);
  selection = model<any>(null);
  filter = input<boolean>(false);
  filterBy = input<string>('label');
  filterPlaceholder = input<string | undefined>(undefined);
  filterMode = input<'lenient' | 'strict'>('lenient');
  loading = input<boolean>(false);
  loadingMode = input<'mask' | 'icon'>('mask'); // 'icon' mode not fully implemented here
  loadingIcon = input<string>('');
  emptyMessage = input<string | undefined>(undefined);
  scrollHeight = input<string | undefined>(undefined);
  indentation = input<number>(1.5); // Default indentation in rem
  propagateSelectionUp = input<boolean>(true);
  propagateSelectionDown = input<boolean>(true);
  // When false, suppresses ALL checkbox tooltips on this tree.
  showTooltips = input<boolean>(true);
  metaKeySelection = input<boolean>(false); // For multiple selection
  nodeTemplate = input<TemplateRef<any> | undefined>(undefined); // Specific template for all nodes
  _templateMap = input<{ [key: string]: TemplateRef<any> } | undefined>(undefined); // For typed nodes

  selectionChange = output<any>();
  nodeSelect = output<{
    originalEvent: Event;
    node: TreeNode;
  }>();
  nodeUnselect = output<{
    originalEvent: Event;
    node: TreeNode;
  }>();
  nodeExpand = output<{
    originalEvent: Event;
    node: TreeNode;
  }>();
  nodeCollapse = output<{
    originalEvent: Event;
    node: TreeNode;
  }>();
  // Emitted when the user clicks the checkbox of a "weak-highlight"
  // (light blue) node. Forwarded verbatim from the tree-node component;
  // the picklist handles it by removing the table from target.
  nodeWeakClick = output<{
    originalEvent: Event;
    node: TreeNode;
  }>();
  onFilter = output<{
    filter: string;
    filteredValue: TreeNode[] | null;
  }>();

  filterInputViewChild = viewChild<ElementRef<HTMLInputElement>>('filterInput');

  visibleNodes: TreeNode[] = [];
  _filteredNodes: TreeNode[] | null = null;
  _filterValue: string = '';
  nodeTouched: boolean = false; // For metaKeySelection on touch devices

  // Basic trackBy function
  trackBy = (index: number, node: TreeNode) => node.key || node;

  ngOnInit() {
    this.updateVisibleNodes();
  }

  ngOnChanges(changes: SimpleChanges) {
    if (changes['value']) {
      this.updateVisibleNodes();
      if (this.hasFilterActive()) {
        this._filter(this._filterValue); // Re-apply filter if value changes
      }
    }
    if (changes['selectionMode'] || changes['selection']) {
      // Potentially update partial selection states if needed
    }
  }

  updateVisibleNodes() {
    this.visibleNodes = this._filteredNodes ?? this.value() ?? [];
    // Initialize parent references and potentially other properties
    this.initializeNodes(null, this.value());
  }

  initializeNodes(parent: TreeNode | null, nodes: TreeNode[] | undefined) {
    if (!nodes) return;
    for (const node of nodes) {
      node.parent = parent ?? undefined; // Set parent reference
      if (node.children) {
        this.initializeNodes(node, node.children);
      }
    }
  }

  onFilterKeyup(event: Event) {
    const value = (event.target as HTMLInputElement).value;
    this._filterValue = value;
    this._filter(value);
  }

  _filter(value: string) {
    const filterValue = value.trim();
    if (filterValue === '') {
      this._filteredNodes = null;
    } else {
      this._filteredNodes = [];
      const searchFields: string[] = this.filterBy().split(',');
      const filterText = filterValue.toLowerCase(); // Basic case-insensitive filter
      const isStrictMode = this.filterMode() === 'strict';

      for (let node of this.value()) {
        const copyNode = { ...node }; // Shallow copy to avoid modifying original
        const params = { searchFields, filterText, isStrictMode };
        if (this.filterNode(copyNode, params)) {
          this._filteredNodes.push(copyNode);
        }
      }
    }
    this.updateVisibleNodes();
    this.onFilter.emit({
      filter: filterValue,
      filteredValue: this._filteredNodes,
    });
  }

  // Recursive function to check if a node or its children match the filter
  filterNode(
    node: TreeNode,
    params: {
      searchFields: string[];
      filterText: string;
      isStrictMode: boolean;
    },
  ): boolean {
    let matched = this.isFilterMatched(node, params);

    if (node.children) {
      let filteredChildren: TreeNode[] = [];
      let childMatched = false;
      for (const childNode of node.children) {
        const copyChild = { ...childNode }; // Shallow copy children too
        if (this.filterNode(copyChild, params)) {
          filteredChildren.push(copyChild);
          childMatched = true;
        }
      }
      node.children = filteredChildren; // Replace children with filtered ones
      // In lenient mode, expand parent if a child matches
      if (!params.isStrictMode && childMatched) {
        node.expanded = true; // Auto-expand filtered nodes
        matched = true;
      }
      // In strict mode, only include parent if it matches directly AND has matched children
      if (params.isStrictMode && matched && !childMatched) {
        matched = false; // Parent matches, but no children do in strict mode
      }
      // If parent doesn't match but children do
      if (!matched && childMatched) {
        matched = true;
      }
    }
    // Ensure leaf nodes are included if they match directly
    if (this.isNodeLeaf(node) && this.isFilterMatched(node, params)) {
      matched = true;
    }

    node.visible = matched; // Mark node visibility based on match
    return matched;
  }

  // Checks if the node itself matches the filter text
  isFilterMatched(
    node: TreeNode,
    params: { searchFields: string[]; filterText: string },
  ): boolean {
    for (const field of params.searchFields) {
      const fieldValue = (node[field] ?? '').toString().toLowerCase();
      if (fieldValue.includes(params.filterText)) {
        return true;
      }
    }
    return false;
  }

  resetFilter() {
    this._filteredNodes = null;
    this._filterValue = '';
    if (this.filterInputViewChild()) {
      this.filterInputViewChild().nativeElement.value = '';
    }
    this.updateVisibleNodes();
    this.onFilter.emit({ filter: '', filteredValue: null });
  }

  hasFilterActive(): boolean {
    return this._filterValue.length > 0;
  }

  handleNodeToggle(event: {
    originalEvent: Event;
    node: TreeNode;
    expanded: boolean;
  }) {
    if (event.expanded) {
      this.nodeExpand.emit({
        originalEvent: event.originalEvent,
        node: event.node,
      });
    } else {
      this.nodeCollapse.emit({
        originalEvent: event.originalEvent,
        node: event.node,
      });
    }
    // Force change detection if needed, though direct property binding should handle it
  }

  handleNodeSelect(event: { originalEvent: Event; node: TreeNode }) {
    const node = event.node;
    const originalEvent = event.originalEvent;

    if (!this.selectionMode() || node.selectable === false) {
      return;
    }

    const isSelected = this.isSelected(node);
    const metaKey =
      (this.metaKeySelection() &&
        !this.nodeTouched &&
        (originalEvent as MouseEvent).ctrlKey) ||
      (originalEvent as MouseEvent).metaKey;

    if (this.selectionMode() === 'single') {
      if (isSelected) {
        this.selection.set(null);
        this.nodeUnselect.emit({ originalEvent, node });
      } else {
        this.selection.set(node);
        this.nodeSelect.emit({ originalEvent, node });
      }
    } else if (this.selectionMode() === 'multiple') {
      if (isSelected) {
        if (metaKey) {
          this.selection.set((this.selection() || []).filter((n) => n.key !== node.key));
          this.nodeUnselect.emit({ originalEvent, node });
        } else {
          this.selection.set([node]);
          this.nodeSelect.emit({ originalEvent, node });
        }
      } else {
        this.selection.set(metaKey ? [...(this.selection() || []), node] : [node]);
        this.nodeSelect.emit({ originalEvent, node });
      }
    } else if (this.selectionMode() === 'checkbox') {
      if (!this.selection()) this.selection.set([]);
      const index = this.findIndexInSelection(node);

      if (index !== -1) {
        // Node is currently selected, deselect it
        if (this.propagateSelectionDown()) this.propagateDown(node, false);
        else {
          const arr = [...this.selection()];
          arr.splice(index, 1);
          this.selection.set(arr);
        }

        if (this.propagateSelectionUp() && node.parent)
          this.propagateUp(node.parent, false);

        this.nodeUnselect.emit({ originalEvent, node });
      } else {
        // Node is not selected, select it
        if (this.propagateSelectionDown()) this.propagateDown(node, true);
        else this.selection.set([...this.selection(), node]);

        if (this.propagateSelectionUp() && node.parent)
          this.propagateUp(node.parent, true);

        this.nodeSelect.emit({ originalEvent, node });
      }
      // Update partial selection states after propagation
      this.updatePartialSelection(this.value());
    }

    this.selectionChange.emit(this.selection());
    this.nodeTouched = false; // Reset touch flag
  }

  handleNodeUnselect(event: { originalEvent: Event; node: TreeNode }) {
    // This is mostly handled within handleNodeSelect now, but keep the output emit
    // If direct unselect logic is needed (e.g., external button), implement here
  }

  findIndexInSelection(node: TreeNode): number {
    if (!this.selection()) return -1;

    if (this.selectionMode() === 'single') {
      return this.selection()?.key === node.key ? 0 : -1;
    } else {
      return (this.selection() as TreeNode[]).findIndex(
        (n) => n.key === node.key,
      );
    }
  }

  isSelected(node: TreeNode): boolean {
    return this.findIndexInSelection(node) !== -1;
  }

  isSelectable(): boolean {
    return this.selectionMode() != null;
  }

  isNodeLeaf(node: TreeNode): boolean {
    return node.leaf === false
      ? false
      : !(node.children && node.children.length > 0);
  }

  isEmpty(): boolean {
    return !this.visibleNodes || this.visibleNodes.length === 0;
  }

  // --- Checkbox Propagation Logic ---

  propagateUp(node: TreeNode, select: boolean) {
    if (!node || !this.value()) return; // Check if node or value is null/undefined

    let selectedCount = 0;
    let childPartialSelected = false;

    if (node.children && node.children.length > 0) {
      for (const child of node.children) {
        if (this.isSelected(child)) {
          selectedCount++;
        } else if (child.partialSelected) {
          childPartialSelected = true;
        }
      }
    } else {
      // Handle case where node might not have children initially
      // or children array is empty
    }

    const nodeIndex = this.findIndexInSelection(node);
    const isNodeSelected = nodeIndex !== -1;

    if (
      select &&
      node.children &&
      selectedCount === node.children.length &&
      !childPartialSelected
    ) {
      // All children selected, select parent if not already selected
      if (!isNodeSelected) {
        this.selection.set([...(this.selection() || []), node]);
      }
      node.partialSelected = false;
    } else {
      // Not all children selected or some are partially selected
      if (isNodeSelected) {
        // Parent is selected, but children aren't fully selected -> deselect parent
        const arr = [...this.selection()];
        arr.splice(nodeIndex, 1);
        this.selection.set(arr);
      }
      // Set partial selection if at least one child is selected or partially selected
      node.partialSelected =
        childPartialSelected ||
        (selectedCount > 0 &&
          (!node.children || selectedCount < node.children.length));
    }

    // Propagate to the parent node
    if (node.parent) {
      this.propagateUp(node.parent, select);
    }
  }

  propagateDown(node: TreeNode, select: boolean) {
    const index = this.findIndexInSelection(node);

    if (select && index === -1) {
      this.selection.set([...(this.selection() || []), node]);
    } else if (!select && index !== -1) {
      const arr = [...this.selection()];
      arr.splice(index, 1);
      this.selection.set(arr);
    }
    node.partialSelected = false; // When propagating down, the node itself is fully selected or deselected

    if (node.children && node.children.length > 0) {
      for (const child of node.children) {
        this.propagateDown(child, select);
      }
    }
  }

  // Call this after selection changes to update visual states
  updatePartialSelection(nodes: TreeNode[] | undefined) {
    if (
      !nodes ||
      this.selectionMode() !== 'checkbox' ||
      !this.propagateSelectionUp()
    )
      return;

    for (const node of nodes) {
      if (!this.isNodeLeaf(node) && node.children) {
        this.updatePartialSelection(node.children); // Update children first

        let selectedCount = 0;
        let childPartialSelected = false;
        for (const child of node.children) {
          if (this.isSelected(child)) {
            selectedCount++;
          } else if (child.partialSelected) {
            childPartialSelected = true;
          }
        }

        const isSelected = this.isSelected(node);
        if (isSelected) {
          node.partialSelected = false; // If selected, cannot be partial
        } else {
          node.partialSelected =
            childPartialSelected ||
            (selectedCount > 0 && selectedCount < node.children.length);
        }
      } else {
        node.partialSelected = false; // Leaf nodes cannot be partial
      }
    }
  }
}

