import { Injectable } from '@angular/core';
import { ApiService } from './api.service';
import { SystemService } from './system.service';
import { StateStoreService } from './state-store.service';

/**
 * Shared Docker lifecycle service — single source of truth for Docker container
 * start/stop commands issued from the UI. Used by both AppsManagerService and
 * StarterPacksComponent (apps and starter packs go through the same backend path).
 *
 * Owns:
 * - In-flight command tracking (so polling can preserve transitional states)
 * - The execute endpoint wrapper
 * - The status-resolution guard logic (preserve 'starting'/'stopping' until Docker
 *   truly reflects the new state — protects long-startup containers like Oracle
 *   from flipping back to 'stopped' mid-transition)
 * - Docker daemon status sync (isDockerInstalled/isDockerDaemonRunning/version)
 */
@Injectable({ providedIn: 'root' })
export class DockerLifecycleService {
  private commandsInFlight = new Set<string>();

  constructor(
    private apiService: ApiService,
    private systemService: SystemService,
    private stateStore: StateStoreService,
  ) {}

  /**
   * Fetch authoritative Docker status from the backend and update the shared
   * stateStore. Only overwrites values when the backend returns valid booleans —
   * guards against transient API failures clearing a known-good state.
   */
  async refreshSystemInfo(): Promise<void> {
    try {
      const backendSystemInfo = await this.systemService.getSystemInfo();
      if (!backendSystemInfo) return;

      const dockerSetup = this.stateStore.configSys.sysInfo.setup.docker;

      if (typeof backendSystemInfo.isDockerInstalled === 'boolean') {
        dockerSetup.isDockerInstalled = backendSystemInfo.isDockerInstalled;
      }
      if (typeof backendSystemInfo.isDockerDaemonRunning === 'boolean') {
        dockerSetup.isDockerDaemonRunning = backendSystemInfo.isDockerDaemonRunning;
      }
      dockerSetup.isDockerOk = dockerSetup.isDockerInstalled && dockerSetup.isDockerDaemonRunning;

      if (backendSystemInfo.dockerVersion && backendSystemInfo.dockerVersion !== 'DOCKER_NOT_INSTALLED') {
        dockerSetup.version = backendSystemInfo.dockerVersion;
      }
    } catch (e) {
      // On API failure, keep existing Docker status (don't set isDockerOk = false)
      console.warn('[DockerLifecycle] Failed to fetch backend system info, keeping existing Docker status', e);
    }
  }

  // --- In-flight tracking ---

  markCommandStart(id: string): void {
    this.commandsInFlight.add(id);
  }

  markCommandEnd(id: string): void {
    this.commandsInFlight.delete(id);
  }

  isCommandInFlight(id: string): boolean {
    return this.commandsInFlight.has(id);
  }

  /** Clear all in-flight markers — call when polling reaches max iterations. */
  clearAllInFlight(): void {
    this.commandsInFlight.clear();
  }

  // --- Execute ---

  /**
   * Execute a Docker lifecycle command (start/stop/reprovision).
   * Both apps and starter packs go through /starter-packs/execute on the backend.
   */
  executeCommand(command: string): Promise<any> {
    return this.apiService.post('/system/services/execute', { command });
  }

  // --- Status guard ---

  /**
   * Decide what status to apply given the current UI status and the newly-observed
   * Docker status. Preserves transitional states while a command is in-flight so
   * long-startup containers don't flicker back to 'stopped' / 'running' before
   * Docker actually reflects the new state.
   *
   * @param id              item id (to look up in-flight state)
   * @param currentStatus   current UI status
   * @param dockerStatus    newly-mapped Docker status, or null if no matching container was found
   * @returns status to apply + whether the caller should clear the in-flight marker
   */
  resolveNextStatus(
    id: string,
    currentStatus: string | undefined,
    dockerStatus: string | null,
  ): { status: string; clearInFlight: boolean } {
    const inFlight = this.commandsInFlight.has(id);

    if (dockerStatus === null) {
      // No container in docker ps
      if (inFlight && currentStatus === 'stopping') {
        // Container gone mid-stop → stop completed
        return { status: 'stopped', clearInFlight: true };
      }
      if (inFlight && currentStatus === 'starting') {
        // Start still in-flight (image downloading, container not yet created) — preserve
        return { status: 'starting', clearInFlight: false };
      }
      // No container + no command → truly stopped
      return { status: 'stopped', clearInFlight: true };
    }

    if (inFlight) {
      // docker compose down still running → container reports 'running' but we're mid-stop
      if (currentStatus === 'stopping' && dockerStatus === 'running') {
        return { status: 'stopping', clearInFlight: false };
      }
      // Long startup (Oracle, etc.) → container not yet healthy → preserve 'starting'
      if (currentStatus === 'starting' && dockerStatus === 'stopped') {
        return { status: 'starting', clearInFlight: false };
      }
    }

    const isStable = dockerStatus !== 'starting' && dockerStatus !== 'stopping';
    return { status: dockerStatus, clearInFlight: isStable };
  }
}

import { Injectable, inject } from '@angular/core';
import { ApiService } from '../../providers/api.service';

@Injectable({
  providedIn: 'root',
})
export class FileExplorerService {
  private endpoint = '/system/fs/explorer';

  private apiService = inject(ApiService);

  /**
   * Get meta information about the file explorer (title, description, quick links)
   */
  async getMetaInfo(): Promise<any> {
    return this.apiService.get(`${this.endpoint}/meta-info`);
  }

  /**
   * Get file tree structure for the specified directory
   * @param directory Directory path to explore
   */
  async getFileTree(directory: string): Promise<any> {
    return this.apiService.get(`${this.endpoint}/file-tree`, {
      dir: encodeURIComponent(directory),
    });
  }

  /**
   * View file content - opens file viewer
   * @param path Full path to the file
   */
  viewFile(path: string): void {
    const url = `${this.apiService.BACKEND_URL}${this.endpoint}/file-viewer?file=${encodeURIComponent(path)}`;
    window.open(url, '_blank');
  }

  /**
   * Download a file
   * @param path Full path to the file
   */
  downloadFile(path: string): void {
    const url = `${this.apiService.BACKEND_URL}${this.endpoint}/file-downloader?file=${encodeURIComponent(path)}`;
    window.location.href = url;
  }

  /**
   * Check if file is viewable by its extension
   * @param filename Name of the file to check
   */
  isViewableFile(filename: string): boolean {
    const viewableExtensions = [
      '.txt',
      '.log',
      '.html',
      '.htm',
      '.xml',
      '.json',
      '.md',
      '.css',
      '.js',
      '.yaml',
      '.yml',
    ];
    return viewableExtensions.some((ext) =>
      filename.toLowerCase().endsWith(ext),
    );
  }

  /**
   * Create a new directory
   * @param path Parent directory path
   * @param dirName Name of the new directory
   */
  async createDirectory(path: string, dirName: string): Promise<boolean> {
    try {
      const fullPath = path.replace(/\/$/, '') + '/' + dirName;
      await this.apiService.post(`/system/fs/dir?path=${encodeURIComponent(fullPath)}`);
      return true;
    } catch (error) {
      console.error('Error creating directory:', error);
      return false;
    }
  }

  /**
   * Delete a file or directory
   * @param path Path to file or directory to delete
   */
  async delete(path: string): Promise<boolean> {
    try {
      return await this.apiService.delete(`/system/fs?path=${encodeURIComponent(path)}`);
    } catch (error) {
      console.error('Error deleting file/directory:', error);
      return false;
    }
  }

  /**
   * Upload a file to the current directory
   * @param directory Current directory path
   * @param file File to upload
   */
  async uploadFile(directory: string, file: File): Promise<boolean> {
    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('dir', directory);

      // Need to handle FormData in your ApiService or modify this approach
      const response = await fetch(
        `${this.apiService.BACKEND_URL}${this.endpoint}/upload`,
        {
          method: 'POST',
          body: formData,
        },
      );

      return response.ok;
    } catch (error) {
      console.error('Error uploading file:', error);
      return false;
    }
  }

  /**
   * Get file content as text
   * @param path Full path to the file
   */
  async getFileContent(path: string): Promise<string> {
    return this.apiService.get(`/system/fs/content`, { path }, undefined, 'text');
  }
}

import { Injectable, inject } from '@angular/core';
import { ApiService } from './api.service';
import Utilities from '../helpers/utilities';

export interface InspectResult {
  name: string;
  type: 'file' | 'dir' | 'symlink';
  size: number;
  absolutePath?: string;
  md5?: string;
  sha1?: string;
  sha256?: string;
  sha512?: string;
  mode?: number;
  accessTime?: Date;
  modifyTime?: Date;
  changeTime?: Date;
  birthTime?: Date;
}

// ANTI-PATTERN WARNING: Injecting FsService in an Angular component or service is almost always
// wrong. Angular apps should consume domain-level APIs (saveReport, loadConfiguration, etc.) and
// let the backend own all path resolution and file I/O. Direct FS calls from the frontend bypass
// the backend's domain model, scatter path knowledge across layers, and make the app brittle to
// deployment layout changes.
//
// The known legitimate exceptions in this codebase are narrow and Electron-specific:
//   • LicenseService  — reads/writes license.xml (a singleton sidecar file with no domain endpoint)
//   • ConfigurationRepository — bootstraps the XML settings file before any domain service exists
//   • ConfigurationComponent — creates the initial folder scaffold on first run
//   • ConnectionDetailsComponent — copies a connection template file before the connection exists
//     (no domain endpoint covers this pre-creation step)
//   • FsService.resolveAbsolutePath — translates a relative path to an absolute one using the
//     backend's PORTABLE_EXECUTABLE_DIR anchor (no other service owns this contract)
//
// Every NEW injection of FsService must be argued at the call site: if a domain-level API could
// handle the operation instead, use that. If you are adding a new caller, add it to the list above.
@Injectable({
  providedIn: 'root',
})
export class FsService {
  protected apiService = inject(ApiService);

  async removeAsync(path: string) {
    //console.log('removeAsync', path);
    return this.apiService.delete(
      `/system/fs?path=${encodeURIComponent(
        Utilities.slash(path),
      )}`,
    );
  }

  async copyAsync(
    sourcePath: string,
    destinationPath: string,
    criteria: {
      overwrite?:
        | boolean
        | ((src: any, dest: any) => boolean | Promise<boolean>);
      matching?: string[];
      ignoreCase?: boolean;
    } = {},
  ): Promise<void> {
    const overwrite =
      typeof criteria.overwrite === 'function'
        ? criteria.overwrite(sourcePath, destinationPath)
        : criteria.overwrite;

    //console.log(`overwrite = ${overwrite}`);

    let postUrl = `/system/fs/copy?fromPath=${encodeURIComponent(
      Utilities.slash(sourcePath),
    )}&toPath=${encodeURIComponent(Utilities.slash(destinationPath))}`;

    if (overwrite) postUrl = `${postUrl}&overwrite=${overwrite}`;
    if (criteria.matching) postUrl = `${postUrl}&matching=${criteria.matching}`;
    if (criteria.matching)
      postUrl = `${postUrl}&ignoreCase=${criteria.ignoreCase}`;

    return this.apiService.post(postUrl);
  }

  async existsAsync(path: string): Promise<'dir' | 'file' | 'other' | false> {
    const result = await this.apiService.get(
      '/system/fs/exists',
      {
        path: encodeURIComponent(Utilities.slash(path)),
      },
      new Headers({
        Accept: 'text/plain',
        'Content-Type': 'application/json',
      }),
    );

    //console.log('existsAsync', path, result);
    // Convert the literal string "false" to the boolean false
    if (result === 'false') {
      return false;
    }

    // Otherwise, return the original result
    return result;
  }

  async dirAsync(
    path: string,
    criteria: {
      empty?: true;
      mode?: string;
    } = {},
  ): Promise<void> {
    return this.apiService.post(
      `/system/fs/dir?path=${encodeURIComponent(Utilities.slash(path))}`,
      criteria,
    );
  }

  async readAsync(path: string): Promise<string> {
    return this.apiService.get(
      '/system/fs/content',
      { path: encodeURIComponent(path) },
      new Headers({
        Accept: 'text/plain',
        'Content-Type': 'application/json',
      }),
    );
  }

  async writeAsync(path: string, content: string) {
    const encodedPath = encodeURIComponent(Utilities.slash(path));
    return this.apiService.put(
      `/system/fs/content?path=${encodedPath}`,
      content,
      new Headers({
        'Content-Type': 'text/plain',
      }),
    );
  }

  async fileAsync(
    path: string,
    criteria: {
      content?: string | Buffer | Object | Array<any>;
      jsonIndent?: number;
      mode?: number | string;
    } = {},
  ): Promise<void> {
    const encodedPath = encodeURIComponent(Utilities.slash(path));

    return this.apiService.post(
      `/system/fs/file?path=${encodedPath}`,
      criteria,
    );
  }

  inspectAsync(
    path: string,
    criteria: {
      checksum?: 'md5' | 'sha1' | 'sha256' | 'sha512';
      mode?: boolean;
      times?: boolean;
      absolutePath?: boolean;
      symlinks?: 'report' | 'follow';
    } = {},
  ): Promise<InspectResult | undefined> {
    return this.apiService.get(
      `/system/fs/inspect/${encodeURIComponent(Utilities.slash(path))}`,
      {
        checksum: criteria.checksum,
        mode: criteria.mode,
        times: criteria.times,
        absolutePath: criteria.absolutePath,
        symlinks: criteria.symlinks,
      },
    );
  }

  async resolveAbsolutePath(relativePath: string): Promise<string> {
    if (relativePath.startsWith('/')) {
      relativePath = relativePath.substring(1);
    }
    const response = await this.apiService.get(
      '/system/fs/resolve',
      { path: relativePath },
    );
    return response.absolutePath;
  }
}

import { ApplicationRef, createComponent, EnvironmentInjector, Injectable } from '@angular/core';
import { InfoDialogComponent } from './info-dialog.component';

@Injectable()
export class InfoService {
  constructor(
    private appRef: ApplicationRef,
    private envInjector: EnvironmentInjector,
  ) {}

  showInformation(options: any): Promise<boolean> {
    return new Promise((resolve) => {
      const ref = createComponent(InfoDialogComponent, {
        environmentInjector: this.envInjector,
      });
      this.appRef.attachView(ref.hostView);
      document.body.appendChild(ref.location.nativeElement);

      const inst = ref.instance;
      inst.title = options.title || 'Information';
      inst.message = options.message;
      inst.confirmLabel = options.confirmLabel || 'OK';

      inst.onClose.subscribe({
        next: (result: boolean) => resolve(result),
        complete: () => {
          setTimeout(() => {
            this.appRef.detachView(ref.hostView);
            ref.destroy();
          }, 300);
        },
      });
    });
  }
}

import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { StateStoreService } from './state-store.service';
import { RbElectronService } from '../areas/electron-nodejs/electron.service';
import { ApiService } from './api.service';
import { ConfigurationRepository } from './configuration-repository.service';
import { firstValueFrom } from 'rxjs';

@Injectable({
  providedIn: 'root',
})
export class InitService {
  constructor(
    private stateStore: StateStoreService,
    private electronService: RbElectronService,
    private apiService: ApiService,
    private settingsService: ConfigurationRepository,
    private http: HttpClient,
  ) { }

  async initialize(): Promise<void> {
    if (this.electronService.isElectron) {
      const backendUrl = await this.electronService.getBackendUrl();
      this.stateStore.configSys.sysInfo.setup.BACKEND_URL = backendUrl;
      // Set API service URL after initialization
      this.apiService.BACKEND_URL = backendUrl;

      // Read API key from file system (secure - no HTTP endpoint exposed)
      const apiKey = await this.electronService.getApiKey();
      if (apiKey) {
        // TEMP: API key disabled during rollback - not setting on ApiService
        // this.apiService.setApiKey(apiKey);
      }

      const systemInfo = await this.electronService.getSystemInfo();
      this.stateStore.configSys.sysInfo.setup.chocolatey = {
        ...systemInfo.chocolatey,
      };
      this.stateStore.configSys.sysInfo.setup.java = { ...systemInfo.java };
      this.stateStore.configSys.sysInfo.setup.env = { ...systemInfo.env };

      // Load internal preferences (skin, copilotUrl, showsamples) once at
      // bootstrap so any feature that reads settingsService.showSamples works
      // regardless of whether the SkinsComponent (which is hidden in
      // RUNNING_IN_E2E mode) ever renders. Without this, the Processing tab's
      // dashboardReports filter sees showSamples=false and hides sample
      // dashboards even though config/_internal/settings.xml says true.
      try {
        const prefs = await this.settingsService.loadPreferences();
        this.settingsService.xmlInternalSettings.documentburster = prefs;
      } catch (e) {
        console.warn('[InitService] Failed to load preferences at bootstrap:', e);
      }
    } else {
      // TEMP (2025-12-19): API key handling is present below but intentionally skipped in web mode during rollback.
      // We return early to avoid accidentally setting an API key in normal web usage until a proper reimplementation is scheduled.
      return;

      try {
        const config = await firstValueFrom(
          this.http.get<{ apiKey?: string }>('/assets/config.json')
        );

        if (config?.apiKey) {
          // API key present: would set if rollback was not active
          this.apiService.setApiKey(config.apiKey);
        } else {
          //console.warn('No API key found in config.json');
        }
      } catch (error) {
          // Fallback API key (dev): would set if rollback not active
          this.apiService.setApiKey("123");
      }

    }
  }
}

import { Injectable, inject } from '@angular/core';
import { ApiService } from './api.service';

export interface JobRecord {
  jobId: string;
  type: string;
  status: 'queued' | 'running' | 'paused' | 'done' | 'failed';
  startedAt: string;
  completedAt?: string;
  resultMetadata?: Record<string, any>;
}

/**
 * Jobs domain service — wraps /api/jobs/* endpoints.
 *
 * Dispatch: submitJob() → POST /api/jobs → 202 + { jobId }
 * Lifecycle: cancelJob(), pauseJob(), resumeJob() → DELETE/PATCH /api/jobs/{id}
 * Status:    getJobStatus() → GET /api/jobs/{id}
 * SSE logs:  openJobLogStream() → GET /api/jobs/{id}/logs (EventSource)
 * List:      getJobs() → GET /api/jobs
 *
 * Housekeeping (not dispatch):
 *   uploadSingle / uploadMultiple / uploadQa — file upload + burst
 *   clearQuarantine — DELETE /api/jobs/quarantine
 *   prepareMergeList — POST /api/jobs/merge-prepare-list
 *   clearResumeJobFile — DELETE /api/jobs/resume-file (pre-C9 paused jobs)
 */
@Injectable({
  providedIn: 'root',
})
export class JobsService {
  protected apiService = inject(ApiService);

  // ========== File uploads ==========

  async uploadSingle(formData: FormData): Promise<any> {
    const customHeaders = new Headers({ Accept: 'application/json' });
    return this.apiService.post('/jobs/upload-and-burst', formData, customHeaders);
  }

  async uploadMultiple(formData: FormData): Promise<any> {
    const customHeaders = new Headers({ Accept: 'application/json' });
    return this.apiService.post('/jobs/upload-and-burst-many', formData, customHeaders);
  }

  async uploadQa(formData: FormData): Promise<any> {
    const customHeaders = new Headers({ Accept: 'application/json' });
    return this.apiService.post('/jobs/upload-and-qa', formData, customHeaders);
  }

  // ========== Async job dispatch ==========

  /** Submit a job. Returns 202 { jobId } — store the id to poll status or cancel. */
  async submitJob(
    type: 'burst' | 'generate' | 'merge',
    params: Record<string, any>,
  ): Promise<{ jobId: string; status: string }> {
    return this.apiService.post('/jobs', { type, ...params });
  }

  // ========== Job lifecycle ==========

  async getJobStatus(jobId: string): Promise<JobRecord> {
    return this.apiService.get(`/jobs/${jobId}`);
  }

  async getJobs(filter?: { status?: string; limit?: number }): Promise<JobRecord[]> {
    const params: Record<string, any> = {};
    if (filter?.status) params['status'] = filter.status;
    if (filter?.limit != null) params['limit'] = filter.limit;
    return this.apiService.get('/jobs', params);
  }

  /** Cancel a running job by UUID. */
  async cancelJob(jobId: string): Promise<void> {
    return this.apiService.delete(`/jobs/${jobId}`);
  }

  /** Pause a running job by UUID. */
  async pauseJob(jobId: string): Promise<void> {
    return this.apiService.patch(`/jobs/${jobId}`, { action: 'pause' });
  }

  /** Resume a paused job by UUID. */
  async resumeJob(jobId: string): Promise<void> {
    return this.apiService.patch(`/jobs/${jobId}`, { action: 'resume' });
  }

  /**
   * Open an SSE stream for per-job status events.
   * Emits { status, id } events: queued → running → done | failed.
   * Caller is responsible for closing the returned EventSource.
   */
  openJobLogStream(jobId: string): EventSource {
    return new EventSource(
      `${this.apiService.BACKEND_URL}/api/jobs/${jobId}/logs`,
    );
  }

  // ========== Housekeeping ==========

  async clearQuarantine(): Promise<any> {
    return this.apiService.delete('/jobs/quarantine');
  }

  async prepareMergeList(filePaths: string[]): Promise<{ listFile: string }> {
    return this.apiService.post('/jobs/merge-prepare-list', { filePaths });
  }

  /**
   * Remove a resume-pending job file that has no UUID in JobStore.
   * Used for jobs that were paused before C9 was introduced.
   */
  async clearResumeJobFile(jobFilePath: string): Promise<void> {
    return this.apiService.delete(
      `/jobs/resume-file?path=${encodeURIComponent(jobFilePath)}`,
    );
  }
}

import { Injectable } from '@angular/core';

import { unserialize } from 'php-serialize';

import * as xml2js from 'xml2js';

import { Changelog, parser } from 'keep-a-changelog';

import * as semver from 'semver';

import Utilities from '../helpers/utilities';
import { ConfigurationRepository } from './configuration-repository.service';
import { AppPathsService } from './app-paths.service';
import { FsService } from './fs.service';
import { ApiService } from './api.service';
import { ReportsService } from './reports.service';

@Injectable({
  providedIn: 'root',
})
export class LicenseService {
  protected licenseFilePath: string;

  licenseDetails: any;

  changeLogStr: string;
  changeLog: Changelog;

  latestVersion: semver.SemVer;
  isNewerVersionAvailable: boolean = false;

  constructor(
    protected settingsService: ConfigurationRepository,
    protected appPathsService: AppPathsService,
    protected reportsService: ReportsService,
    protected fsService: FsService,
    protected apiService: ApiService,
  ) {
    this.licenseFilePath = Utilities.slash(
      `${this.appPathsService.CONFIGURATION_FOLDER_PATH}/_internal/license.xml`,
    );
  }

  async saveLicense() {
    //console.log(
    //  `saveLicenseFileAsync - this.licenseDetails = ${JSON.stringify(
    //    this.licenseDetails,
    //  )}`,
    //);

    const builder = new xml2js.Builder();

    const licenseDetailsAsString = builder.buildObject(this.licenseDetails);

    //console.log(
    //  `saveLicenseFileAsync - licenseDetailsAsString = ${licenseDetailsAsString}`
    //);

    return this.fsService.writeAsync(
      this.licenseFilePath,
      licenseDetailsAsString,
    );
  }

  async loadLicense() {
    //if (this.latestVersion) return;

    //console.log(`this.latestVersion = ${this.latestVersion}`);

    //console.log(`license.service.loadLicenseFileAsync()`);

    const content = await this.fsService.readAsync(this.licenseFilePath);

    //console.log(`license.service.content = ${JSON.stringify(content)}`);

    this.licenseDetails = await Utilities.parseStringPromise(content, {
      trim: true,
      explicitArray: false,
    });

    // console.log(
    //   `loadLicenseFileAsync - this.licenseDetails = ${JSON.stringify(
    //     this.licenseDetails
    //   )}`
    // );

    if (this.licenseDetails.license.latestversion) {
      this.latestVersion = this.licenseDetails.license.latestversion;
      this.changeLogStr = this.licenseDetails.license.changelog;
    } // if it is a demo installation
    else {
      let changeLogResponseAsJson: any;

      try {
        changeLogResponseAsJson =
          await this.getChangeLogForTheDemoInstallationToo();
        //console.log(
        //  `changeLogResponseAsJson = ${JSON.stringify(changeLogResponseAsJson)}`,
        //);

        this.latestVersion = changeLogResponseAsJson.new_version;

        const { changelog } = unserialize(changeLogResponseAsJson.sections, {
          description: String,
          changelog: String,
        });
        this.changeLogStr = changelog;
      } catch {
        // Silently ignore changelog fetch failures (expected for demo/offline installations)
      }
    }

    this.isNewerVersionAvailable = false;

    if (!this.reportsService.version)
      await this.reportsService.loadDefaults();

    if (this.latestVersion && this.reportsService.version) {
      this.latestVersion = semver.coerce(this.latestVersion);
      this.reportsService.version = semver.coerce(
        this.reportsService.version,
      );

      //console.log(
      //  `this.latestVersion = ${this.latestVersion}, this.settingsService.version = ${this.settingsService.version}`
      //);

      if (semver.gt(this.latestVersion, this.reportsService.version)) {
        this.isNewerVersionAvailable = true;
      }
    }
    try {
      //the "Improved software changelog" keepachangelog format was implemented in
      //DocumentBurster v8.8.0
      this.changeLog = parser(this.changeLogStr);
    } catch {}
  }

  getChangeLogForTheDemoInstallationToo(): Promise<any> {
    return this.apiService.get(
      `/system/info/changelog?itemName=${encodeURIComponent(this.settingsService.product)}`,
    );
  }

  verifyLicense(action, exitCallback?): Promise<void> {
    const call =
      action === 'check'
        ? this.apiService.get('/system/license/status')
        : this.apiService.post(`/system/license/${action}`, {});
    return call.then(() => {
      if (exitCallback) exitCallback();
    });
  }

  deActivateLicense(exitCallback?) {
    return this.apiService.post('/system/license/deactivate', {}).then(() => {
      if (exitCallback) exitCallback();
    });
  }
}

