import { Injectable } from '@angular/core';
import { Changelog, Release } from 'keep-a-changelog';
import { ConfigInfo } from '../models/config-info.model';
import { SystemInfo } from '../models/system-info.model';
import { BlogPostInfo } from '../models/blog-post-info.model';

@Injectable({
  providedIn: 'root',
})
export class StateStoreService {
  //Configuration
  configSys = {
    currentConfigFile: ConfigInfo,
    allConfigFiles: [ConfigInfo],
    sysInfo: SystemInfo,
    info: {
      SHOULD_SEND_STATS: true,
      PORTABLE_EXECUTABLE_DIR: '',
      CONFIGURATION_FOLDER_PATH: '',
      LOGS_FOLDER_PATH: '',
      JOBS_FOLDER_PATH: '',
      QUARANTINED_FOLDER_PATH: '',
      UPDATE_JAR_FILE_PATH: '',
      FRONTEND: 'electron',
      isServerVersion: false,
      product: 'DocumentBurster',
      version: '9.1',
    },
  };

  //Execution Stats
  exec = {
    logStats: {
      infoLogFilePath: '',
      errorsLogFilePath: '',
      warningsLogFilePath: '',
      bashServiceLogFilePath: '',
      updateErrMessage: '',
      infoLogFileIsLocked: false,
      errorsLogFileIsLocked: false,
      warningsLogFileIsLocked: false,
      bashServiceLogFileIsLocked: false,
      infoLogFileSize: -1,
      errorsLogFileSize: -1,
      warningsLogFileSize: -1,
      bashServiceLogFileSize: -1,
    },
    jobStats: {
      progressValue: 0,
      numberOfActiveJobs: 0,
      progressJobFileExists: 0,
      pauseJobFileExists: 0,
      cancelJobFileExists: 0,
      workingOnJobs: [
        {
          fileName: '',
          jobFilePath: '',
        },
      ],
      workingOnFileNames: [],
      niceWorkingOnFileNames: '',
      jobsToResume: [],
    },
  };

  areas = {
    processing: {
      tabs: {
        burst: {
          filePath: '',
        },
      },
    },
  };

  license = {
    key: '',
    status: '',
    customerName: '',
  };

  product = {
    name: 'DocumentBurster',
    version: '8.8.1',
    latestVersion: '',
    changeLog:
      '# DocumentBurster<br><br>All notable changes to this project will be documented in this file.',
    isNewerVersionAvailable: false,
  };

  modals = {
    htmlCodeToPreview: '',
    modalSMSInfo: {
      isModalSMSVisible: false,
      fromNumber: '',
      toNumber: '',
    },
  };

  terminal = {
    readOnly: true,
    availableCommandsVisible: false,
  };

  whatsNew = {
    blogPosts: [BlogPostInfo],
    visibleBlogPost: BlogPostInfo,
    visibleBlogPostIndex: -1,
    changeLogMarkdown: '',
    // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
    changeLog: Changelog,
    // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
    visibleRelease: Release,
    visibleReleaseIndex: -1,
    visibleReleaseDate: '',
    visibleReleaseBlogPostAnnouncement: [BlogPostInfo],
  };

  clearCurrentConfiguration = () => {
    this.configSys.currentConfigFile.fileName = '';
    this.configSys.currentConfigFile.filePath = '';
    this.configSys.currentConfigFile.configuration.settings.template = '';
  };
}

import { Injectable, inject } from '@angular/core';
import { ApiService } from './api.service';

/**
 * System domain service — wraps /api/system/* endpoints.
 * Consolidates system status, info, and utility calls that were
 * previously duplicated across starter-packs, apps-manager, and processing components.
 */
@Injectable({
  providedIn: 'root',
})
export class SystemService {
  protected apiService = inject(ApiService);

  async getServicesStatus(skipProbe?: boolean): Promise<any> {
    return this.apiService.get('/system/services/status', { skipProbe });
  }

  async getSystemInfo(): Promise<any> {
    return this.apiService.get('/system/info');
  }

  async checkUrl(url: string): Promise<any> {
    return this.apiService.get('/system/test-url', { url });
  }

  async getBlogPosts(): Promise<any> {
    return this.apiService.get('/system/info/news');
  }

  async getChangelog(itemName: string): Promise<any> {
    return this.apiService.get(
      `/system/info/changelog?itemName=${encodeURIComponent(itemName)}`,
    );
  }
}

import { Injectable } from '@angular/core';

type ToastType = 'success' | 'info' | 'error' | 'warning';

const TYPE_CLASS: Record<ToastType, string> = {
  success: 'alert-success',
  info:    'alert-info',
  error:   'alert-error',
  warning: 'alert-warning',
};

@Injectable()
export class ToastrMessagesService {
  private show(type: ToastType, message = '', title = '', timeoutMs = 5000): void {
    const container = document.createElement('div');
    container.className = 'toast toast-end toast-bottom';
    container.style.cssText = 'z-index:10000;position:fixed;bottom:1rem;right:1rem;';

    const alert = document.createElement('div');
    alert.className = `alert ${TYPE_CLASS[type]}`;
    alert.style.cssText = 'max-width:320px;word-break:break-word;';
    alert.innerHTML = title ? `<strong>${title}</strong> ${message}` : message;

    container.appendChild(alert);
    document.body.appendChild(container);

    setTimeout(() => container.remove(), timeoutMs);
  }

  showSuccess(message?: string, title?: string, override?: {}) {
    this.show('success', message, title);
  }

  showInfo(message?: string, title?: string, override?: {}) {
    this.show('info', message, title);
  }

  showError(message?: string, title?: string, override?: {}) {
    this.show('error', message, title);
  }

  showWarning(message?: string, title?: string, override?: {}) {
    this.show('warning', message, title);
  }
}

