export class Constants {
  public static WS_ENDPOINT = '/ws';
  public static WS_TOPIC_TAILER = '/topic/tailer';
  public static WS_TOPIC_EXECUTION_STATS = '/topic/execution-stats';
  public static MAX_PROGRESS_LENGTH = 100;
}

import { Injectable, inject } from '@angular/core';

import type {
  SaveDialogOptions,
  SaveDialogReturnValue,
