      //console.log(
      //  `Log 7 - homeDirectoryPath = ${homeDirectoryPath}, upgdDbFromFolderPath = ${upgdDbFromFolderPath}`,
      //);

      await UtilitiesNodeJs.copyAsync(homeDirectoryPath, upgdDbFromFolderPath);
