import * as xml2js from 'xml2js';
import Utilities from '../../helpers/utilities';

// Node-builtin + native-deps access via window.require so esbuild's static
// analyzer treats this as a property access (not a module import) and never
// tries to resolve `fs`, `path`, `os`, etc. at build time. The Electron
// renderer always exposes window.require; this file is never reached in the
// web build (electron.service.ts is swapped for electron.service.empty-web.ts
// via angular.json fileReplacements, which severs all imports into here).
const fs      = (window as any).require('fs');
const AdmZip  = (window as any).require('adm-zip');
const path    = (window as any).require('path');
const os      = (window as any).require('os');
const jetpack = (window as any).require('fs-jetpack');

export default class UtilitiesNodeJs {
  static pathResolve(pathSegments: string[]): string {
    return path.resolve(...pathSegments);
  }

  static osTmpDir(): string {
    return os.tmpdir();
  }

  static async download(
    sourceUrl: string,
    targetFile: string,
    progressCallback?: (bytesDone: number, percent: number) => void,
    length?: number,
  ) {
    const request = new Request(sourceUrl, {
      headers: new Headers({ 'Content-Type': 'application/octet-stream' }),
    });

    const response = await fetch(request);
    if (!response.ok) {
      throw Error(
        `Unable to download, server returned ${response.status} ${response.statusText}`,
      );
    }

    const body = response.body;
    if (body == null) {
      throw Error('No response body');
    }

    const finalLength =
      length || parseInt(response.headers.get('Content-Length') || '0', 10);
    const reader = body.getReader();
    const writer = fs.createWriteStream(targetFile);

    await this.streamWithProgress(
      finalLength,
      reader,
      writer,
      progressCallback,
    );
    writer.end();
  }

  static async streamWithProgress(
    length: number,
    reader: ReadableStreamDefaultReader<Uint8Array>,
    writer: NodeJS.WriteStream,
    progressCallback?: (bytesDone: number, percent: number) => void,
  ) {
    let bytesDone = 0;

    while (true) {
      //const result = await reader.read(new Uint8Array(length));
      const result = await reader.read();
      if (result.done) {
        if (progressCallback != null) {
          progressCallback(length, 100);
        }
        return;
      }

      const decoder = new TextDecoder();
      const chunk = result.value;
      const str = decoder.decode(chunk);
      if (chunk == null) {
        throw Error('Empty chunk received during download');
      } else {
        writer.write(str);
        if (progressCallback != null) {
          bytesDone += chunk.byteLength;
          const percent =
            length === 0 ? null : Math.floor((bytesDone / length) * 100);
          progressCallback(bytesDone, percent);
        }
      }
    }
  }

  static extractAllTo(targetFile: string, targetPath: string) {
    new AdmZip(targetFile).extractAllTo(
      Utilities.slash(Utilities.dirname(targetFile)),
    );
  }

  static writeZip(targetFile: string, targetPath: string) {
    const zip = new AdmZip();
    zip.addLocalFolder(targetPath);

    zip.writeZip(targetFile);
  }

  //jetpack stuff
  static async dirAsync(
    pathFolder: string,
    criteria?: {
      empty?: boolean;
      mode?: number | string;
    },
  ) {
    return jetpack.dirAsync(pathFolder, criteria);
  }

  static async copyAsync(
    from: string,
    to: string,
    options?: {
      overwrite?:
        | boolean
        | ((source: any, destination: any) => boolean | Promise<boolean>);
      matching?: string[];
      ignoreCase?: boolean;
    },
  ) {
    return await jetpack.copyAsync(from, to, options);
  }

  static async moveAsync(
    from: string,
    to: string,
    options?: {
      overwrite?: false;
    },
  ) {
    return await jetpack.moveAsync(from, to, options);
  }

  static async existsAsync(filePath: string) {
    return await jetpack.existsAsync(filePath);
  }

  static async removeAsync(filePath: string) {
    return await jetpack.removeAsync(filePath);
  }

  static async writeAsync(filePath: string, content: string) {
    return await jetpack.writeAsync(filePath, content);
  }

  static async appendAsync(filePath: string, content: string) {
    return await jetpack.appendAsync(filePath, content);
  }

  static async readAsync(filePath: string) {
    return await jetpack.readAsync(filePath);
  }

  static async findAsync(
    path: string = '.',
    options: {
      matching?: string[];
      filter?: (inspectObj: any) => boolean;
      files?: boolean;
      directories?: boolean;
      recursive?: boolean;
      ignoreCase?: boolean;
    } = {
      matching: ['*'],
      files: true,
      directories: false,
      recursive: true,
      ignoreCase: false,
    },
  ) {
    return await jetpack.findAsync(path, options);
  }

  //end jetpack stuff

  //settings stuff
  static async saveSettingsFileAsync(settings: {}, filePath: string) {
    //console.log(`filePath: ${filePath}`);
    //console.log(`settings: ${JSON.stringify(settings)}`);

    try {
      await UtilitiesNodeJs.removeAsync(filePath);
      //await this.fs.unlink(filePath);
    } catch (error) {
    } finally {
      const builder = new xml2js.Builder();
      return UtilitiesNodeJs.writeAsync(
        filePath,
        builder.buildObject(settings),
      );

      //return this.fs.writeFile(filePath, '123');
    }
  }

  // loadSettingsFileAsync — used by updater.ts during auto-update
  // (server may not be running during update, so local file access is needed)
  static async loadSettingsFileAsync(filePath: string): Promise<any> {
    //console.trace();

    const content = await UtilitiesNodeJs.readAsync(filePath);

    const parsedString = await Utilities.parseStringPromise(content, {
      trim: true,
      explicitArray: false,
      valueProcessors: [xml2js.processors.parseBooleans],
    });

    //XML files from older versions (i.e. v5) do not contain attachments
    if (parsedString.documentburster.settings.attachments) {
      if (
        parsedString.documentburster.settings.attachments.items.attachmentItems
      ) {
        if (
          !Array.isArray(
            parsedString.documentburster.settings.attachments.items
              .attachmentItems,
          )
        ) {
          parsedString.documentburster.settings.attachments.items.attachmentItems =
            [
              parsedString.documentburster.settings.attachments.itemsItems
                .attachment,
            ];
        }
      } else {
        parsedString.documentburster.settings.attachments.items = {};
        parsedString.documentburster.settings.attachments.items.attachment = [];
      }
    }

    return parsedString;
  }

  //end settings stuff (loadReportingFileAsync, loadPreferencesFileAsync, loadFileContentAsync removed — now handled by server API)
}

import { Observable, Subscriber } from 'rxjs';
import Stomp from 'stompjs';
import SockJS from 'sockjs-client';

export class WebSocketEndpoint {
  BACKEND_URL = '/api';

  wsSubscriptions = [];

  _topicsOptions: TopicOptions[];

  socketUrl: string;
  accessToken?: string;
  reconnectionTimeout: number = 30000;

  _socket: SocketEndpoint = new SocketEndpoint();

  observableStompConnection!: Observable<any>;
  subscribers: Array<any> = [];
  subscriberIndex: number = 0;

  _messageIds: Array<any> = [];

  reconnectionPromise: any;

  constructor() {}

  async makeWSConnection(topicsOptions: TopicOptions[]) {
    this._topicsOptions = topicsOptions;
    this.createObservableSocket();
    return this.connect();
  }

  //TO BE OVERIDDEN
  getOptions = () => {
    return {};
  };

  private createObservableSocket = () => {
    this.observableStompConnection = new Observable((observer) => {
      const subscriberIndex = this.subscriberIndex++;
      this.addToSubscribers({ index: subscriberIndex, observer });
      return () => this.removeFromSubscribers(subscriberIndex);
    });
  };

  addToSubscribers = (subscriber: {
    index: number;
    observer: Subscriber<any>;
  }) => {
    this.subscribers.push(subscriber);
  };

  removeFromSubscribers = (index: number) => {
    if (index > this.subscribers.length)
      throw new Error(
        `Unexpected error removing subscriber from websocket, because index ${index} is greater than subscriber length ${this.subscribers.length}`,
      );
    this.subscribers.splice(index, 1);
  };

  getObservable = () => {
    return this.observableStompConnection;
  };

  getMessage = (data: { body: string; headers: { [x: string]: any } }) => {
    let out: any = {};
    out.type = 'SUCCESS';
    out.message = JSON.parse(data.body);
    out.headers = {};
    out.headers.messageId = data.headers['message-id'];

    let messageIdIndex = this._messageIds.indexOf(out.headers.messageId);
    if (messageIdIndex > -1) {
      out.self = true;
      this._messageIds = this._messageIds.splice(messageIdIndex, 1);
    }
    return out;
  };

  _socketListener = () => {
    if (!this._socket.stomp.connected) {
      //console.log('Connection not ready, retrying...');
      setTimeout(this._socketListener, 1000); // retry after 1 second
      return;
    }

    this._topicsOptions.forEach((topicOptions) => {
      const wsSubscription = this._socket.stomp.subscribe(
        topicOptions.topicName,
        (data: any) => {
          //console.log(`Received data: ${JSON.stringify(data)}`);
          const result = topicOptions.processDataCallback(data.body);
          //console.log(`Processed data: ${JSON.stringify(result)}`);
          this.subscribers.forEach((subscriber) =>
            subscriber.observer.next(result),
          );
        },
      );

      this.wsSubscriptions.push(wsSubscription);
    });
  };

  _onSocketError = (errorMsg: any) => {
    //console.log(`WebSocket _onSocketError ${errorMsg}`);

    let out: any = {};
    out.type = 'ERROR';
    out.message = errorMsg;
    this.subscribers.forEach((subscriber) => subscriber.observer.error(out));
    this.scheduleReconnection();
  };

  scheduleReconnection = () => {
    if (this.reconnectionPromise) {
      clearTimeout(this.reconnectionPromise);
    }
    this.reconnectionPromise = setTimeout(() => {
      //console.log(
      //  'Socket reconnecting... (if it fails, next attempt in ' +
      //    this.reconnectionTimeout +
      //    ' msec)',
      //);
      this.connect();
    }, this.reconnectionTimeout);
  };

  reconnectNow = function (this: WebSocketEndpoint) {
    this._socket.stomp.disconnect();
    if (this.reconnectionPromise && this.reconnectionPromise.cancel)
      this.reconnectionPromise.cancel();
    this.connect();
  };

  connect = async () => {
    // Build connection headers for STOMP
    // For Electron: include API key in headers
    // For Web: session cookie is sent automatically by SockJS
    const headers: { [key: string]: string } = {};

    let socketUrl = this.BACKEND_URL + this.socketUrl;
    
    // TEMP: API key / access_token disabled during rollback
    // if (this.accessToken) {
    //   socketUrl += `?access_token=${encodeURIComponent(this.accessToken)}`;
    //   headers['X-API-Key'] = this.accessToken;
    // }
    // For Web mode: SockJS automatically includes cookies (JSESSIONID)
    // No additional headers needed - session authentication is automatic

    this._socket.client = new SockJS(socketUrl);

    this._socket.client.discardWebsocketOnCommFailure = true;
    this._socket.client.connectionTimeout = 500;

    this._socket.stomp = Stomp.over(this._socket.client);
    //this._socket.stomp = Stomp.over(
    //  () => new WebSocket(this._socket.client.url.replace('http', 'ws')),
    //);

    //disable logging
    this._socket.stomp.debug = () => {};
    this._socket.stomp.onclose = this.scheduleReconnection;

    return this._socket.stomp.connect(
      headers,
      this._socketListener,
      this._onSocketError,
    );
  };
}

class SocketEndpoint {
  client: any;
  stomp: any;
}
