      try {
        const row = payload?.row;
        if (row && typeof row.getElement === 'function') {
          const el = row.getElement();
          el.style.backgroundColor = params?.color || '#ffdddd';
        }
      } catch (e) {
        console.warn('HIGHLIGHT_URGENT handler error', e);
      }
    },
