          entryTemplate:
            '<a href="{url}" target="_blank"><h4>{title}</h4></a><br><br>{shortBodyPlain} <a href="{url}" target="_blank"> ... Read More</a><hr>',
        }
      );
      return this.rssParser.render();
    }
    */
  }
}

