                <td [attr.colspan]="totalColumns - loadInviteColumnIndex" style="padding: 4px 12px 6px; border-top: none; background: #f4f9fc;">
                  <a id="btnLoadInvite_{{configurationFile.folderName}}_{{configurationFile.fileName}}"
