      (click)="closeTemplateGallery()">
      {{ 'AREAS.CONFIGURATION.TAB-REPORT-TEMPLATE-OUTPUT.BUTTONS.CLOSE' | translate }}
    </button>
  </div>
</div>
</dp-dialog>`;

