    SystemDiagnosticsComponent,
  ],
  exports: [
    JavaComponent,
    ExtraPackagesComponent,
    TerminalComponent,
    UpdateComponent,
    SystemDiagnosticsComponent,
  ],
  providers: [RbElectronService],
