  template: '',
})
export class SystemDiagnosticsComponent {}

@NgModule({
  declarations: [
    JavaComponent,
    ExtraPackagesComponent,
    TerminalComponent,
    UpdateComponent,
    SystemDiagnosticsComponent,
  ],
