  @if (stateStore.configSys.sysInfo.setup.chocolatey.isChocoOk) {
    <div>
      <span [innerHTML]="'AREAS.INSTALL-SETUP-UPGRADE.COMPONENTS.EXTRA-PACKAGES.INNER-HTML.ABOUT' | translate"></span>
